import React, { useState, useEffect } from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  LabelList
} from 'recharts';
import { DashboardData, VisualConfig } from '../types';
import { THEMES, TRANSLATIONS } from '../constants';
import { formatNumber, getContrastColor } from '../utils';

const useChartDimensions = () => {
  const [dims, setDims] = useState({ 
    tooltip: 14,
    dotRadius: 4,
    dotActive: 6,
    strokeWidth: 3,
    margin: { top: 20, right: 30, left: 10, bottom: 20 }
  });

  useEffect(() => {
    const update = () => {
      const w = window.innerWidth;
      if (w >= 3000) { // ~4k
         setDims({ 
           tooltip: 32,
           dotRadius: 8,
           dotActive: 12,
           strokeWidth: 6,
           margin: { top: 40, right: 60, left: 20, bottom: 40 }
         });
      } else if (w >= 2000) { // ~2k
         setDims({ 
           tooltip: 24,
           dotRadius: 6,
           dotActive: 9,
           strokeWidth: 4,
           margin: { top: 30, right: 40, left: 15, bottom: 30 }
         });
      } else if (w >= 1536) { // Large Laptop
         setDims({ 
           tooltip: 16,
           dotRadius: 5,
           dotActive: 7,
           strokeWidth: 3,
           margin: { top: 20, right: 30, left: 10, bottom: 20 }
         });
      } else {
         setDims({ 
           tooltip: 14,
           dotRadius: 4,
           dotActive: 6,
           strokeWidth: 3,
           margin: { top: 20, right: 30, left: 10, bottom: 20 }
         });
      }
    };
    window.addEventListener('resize', update);
    update();
    return () => window.removeEventListener('resize', update);
  }, []);
  return dims;
};

const ChartLegend = ({ items, iconType = 'circle' }: { items: any[], iconType?: 'circle' | 'rect' }) => {
  if (!items || items.length === 0) return null;

  return (
    <div className="flex flex-wrap justify-center items-center gap-x-6 gap-y-3 pb-4 px-4 w-full border-b border-transparent">
       {items.map((entry: any, index: number) => (
         <div key={`legend-item-${index}`} className="flex items-center min-w-0">
            <div 
               style={{ backgroundColor: entry.color }}
               className={`w-4 h-4 lg:w-5 lg:h-5 min-[2000px]:w-6 min-[2000px]:h-6 min-[3000px]:w-8 min-[3000px]:h-8 mr-3 shrink-0 border border-slate-200 ${iconType === 'circle' ? 'rounded-full' : 'rounded-[2px]'}`}
            />
            <span className="text-sm sm:text-base lg:text-lg 2xl:text-xl min-[2000px]:text-2xl min-[3000px]:text-4xl font-bold text-slate-700 leading-tight whitespace-nowrap">
               {entry.value}
            </span>
         </div>
       ))}
    </div>
  );
};

const CustomTooltip = ({ active, payload, label, dims, lang }: any) => {
  if (active && payload && payload.length) {
    return (
      <div style={{
        backgroundColor: 'rgba(255, 255, 255, 0.96)',
        border: '1px solid #e2e8f0',
        borderRadius: '16px',
        padding: '16px',
        boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)',
        fontSize: `${dims.tooltip}px`,
        fontWeight: '700',
        color: '#1e293b'
      }}>
        <p className="mb-2 border-b border-slate-100 pb-2">{label}</p>
        {payload.map((entry: any, index: number) => (
          <div key={index} style={{ color: entry.color || entry.fill }} className="flex items-center gap-2 mb-1">
            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color || entry.fill }}></span>
            <span>{entry.name}: {formatNumber(entry.value, lang)}</span>
          </div>
        ))}
      </div>
    );
  }
  return null;
};

const CHART_LABELS = {
  en: { aioKeywords: 'Phrases with AI answers', domainInAio: 'Domain in AI answers', pages: 'Total Indexed Pages' },
  ua: { aioKeywords: 'Фрази з AI відповідями', domainInAio: 'Домен в AI відповідях', pages: 'Проіндексовані сторінки' }
};

export const HistoryComparisonChart: React.FC<{ 
  data: DashboardData, 
  metric: 'visible' | 'traff' | 'keywords', 
  lang: 'en' | 'ua', 
  config: VisualConfig
}> = ({ data, metric, lang, config }) => {
  const domains = Object.keys(data);
  const dims = useChartDimensions();
  if (domains.length === 0) return null;
  const colors = THEMES[config.style].line;

  const allMonths = Array.from(new Set(domains.flatMap(d => 
    data[d].history.map(h => h.date.substring(0, 7))
  ))).sort();

  const chartData = allMonths.map(monthStr => {
    const entry: any = { month: monthStr };
    domains.forEach(d => {
      const monthItems = data[d].history.filter(h => h.date.startsWith(monthStr));
      if (monthItems.length > 0) {
        const latest = monthItems.sort((a, b) => b.date.localeCompare(a.date))[0];
        entry[d] = latest[metric];
      } else {
        entry[d] = null;
      }
    });
    return entry;
  });

  const sortedDomains = domains;
  const legendItems = sortedDomains.map((d, i) => ({
    value: d,
    color: colors[i % colors.length]
  }));

  return (
    <div className="w-full h-full flex flex-col">
      <ChartLegend items={legendItems} iconType="circle" />
      <div className="flex-1 min-h-0 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={chartData} margin={dims.margin}>
            <CartesianGrid vertical={false} stroke="#e2e8f0" strokeDasharray="3 3" />
            <XAxis 
              dataKey="month" 
              interval="preserveStartEnd"
              padding={{ left: 20, right: 20 }}
              stroke="#64748b" 
              fontSize={config.axisFontSize} 
              fontWeight="600"
              tickLine={false} 
              axisLine={false} 
              dy={config.axisFontSize * 1.2} 
              tickFormatter={(str) => { 
                const [y, m] = str.split('-'); 
                return `${parseInt(m).toString().padStart(2, '0')}.${y.substring(2)}`; 
              }} 
            />
            <YAxis 
              stroke="#64748b" 
              fontSize={config.axisFontSize} 
              fontWeight="600" 
              tickLine={false} 
              axisLine={false}
              width={config.axisFontSize * 6}
              tickFormatter={(v) => formatNumber(v, lang)} 
            />
            <Tooltip content={<CustomTooltip dims={dims} lang={lang} />} />
            {sortedDomains.map((d, i) => (
              <Line 
                key={d} 
                name={d} 
                type="monotone" 
                dataKey={d} 
                stroke={colors[i % colors.length]} 
                strokeWidth={dims.strokeWidth} 
                dot={{ r: dims.dotRadius, strokeWidth: Math.max(1, dims.strokeWidth - 2), fill: colors[i % colors.length], stroke: 'white' }} 
                activeDot={{ r: dims.dotActive, strokeWidth: dims.strokeWidth, stroke: 'white' }} 
                connectNulls 
                isAnimationActive={true}
                animationDuration={1500}
              >
                {config.showValues && (
                  <LabelList 
                    dataKey={d} 
                    position="top" 
                    offset={10 + config.labelOffset} 
                    fontSize={config.labelFontSize} 
                    fontWeight="700" 
                    fill={colors[i % colors.length]} 
                    formatter={(v: any) => v ? formatNumber(v, lang) : ''} 
                  />
                )}
              </Line>
            ))}
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export const StackedPositionChart: React.FC<{ 
  data: DashboardData, 
  lang: 'en' | 'ua',
  config: VisualConfig
}> = ({ data, lang, config }) => {
  const domains = Object.keys(data);
  const dims = useChartDimensions();
  const stackColors = THEMES[config.style].stack;

  const chartData = domains.map(d => {
    const p = data[d].positions;
    const total = p.range1 + p.range2_3 + p.range4_10 + p.range11_20 + p.range21_50 + p.range51_100;
    return {
      name: d,
      total,
      range1: p.range1,
      range2_3: p.range2_3,
      range4_10: p.range4_10,
      range11_20: p.range11_20,
      range21_50: p.range21_50,
      range51_100: p.range51_100,
    };
  }).sort((a, b) => b.total - a.total); 

  const seriesKeys = [
    { key: 'range1', name: '1', color: stackColors[0] },
    { key: 'range2_3', name: '2 - 3', color: stackColors[1] },
    { key: 'range4_10', name: '4 - 10', color: stackColors[2] },
    { key: 'range11_20', name: '11 - 20', color: stackColors[3] },
    { key: 'range21_50', name: '21 - 50', color: stackColors[4] },
    { key: 'range51_100', name: '51 - 100', color: stackColors[5] },
  ];

  const legendItems = seriesKeys.map(s => ({ value: s.name, color: s.color }));

  return (
    <div className="w-full h-full flex flex-col">
      <ChartLegend items={legendItems} iconType="rect" />
      <div className="flex-1 min-h-0 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={chartData} margin={{...dims.margin, bottom: dims.margin.bottom + 40}}>
            <CartesianGrid vertical={false} stroke="#e2e8f0" strokeDasharray="3 3" />
            <XAxis 
              dataKey="name" 
              stroke="#1e293b" 
              fontSize={config.axisFontSize} 
              fontWeight="700" 
              tickLine={false} 
              axisLine={false} 
              dy={10}
              angle={-35} 
              textAnchor="end" 
              interval={0}
            />
            <YAxis 
              stroke="#64748b" 
              fontSize={config.axisFontSize} 
              fontWeight="600" 
              tickLine={false} 
              axisLine={false} 
              width={config.axisFontSize * 6} 
              tickFormatter={(v) => formatNumber(v, lang)} 
            />
            <Tooltip content={<CustomTooltip dims={dims} lang={lang} />} cursor={{fill: '#f1f5f9', opacity: 0.5}} />
            {seriesKeys.map((s, idx) => (
              <Bar 
                key={s.key}
                name={s.name} 
                dataKey={s.key} 
                stackId="distribution" 
                fill={s.color} 
                isAnimationActive={true} 
                animationDuration={1000 + (idx * 150)}
                radius={idx === seriesKeys.length - 1 ? [6, 6, 0, 0] : [0, 0, 0, 0]} 
              >
                 {config.showValues && (
                   <LabelList 
                      dataKey={s.key} 
                      position="inside"
                      dy={config.labelOffset}
                      fill={getContrastColor(s.color)} 
                      fontSize={config.labelFontSize} 
                      fontWeight="700" 
                      formatter={(v: number) => {
                         if (!v || v <= 0) return '';
                         if (v < 3) return ''; 
                         return formatNumber(v, lang);
                      }} 
                   />
                 )}
              </Bar>
            ))}
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

