import { useState, useRef, useEffect } from 'react';
import htmlToImage from 'html-to-image';

interface Props {
  isFullscreenReport?: boolean;
}

const App = ({ isFullscreenReport }: Props) => {
  const [isReady, setIsReady] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);
  const fullscreenRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setIsReady(true);
  }, []);

  const handleScreenshot = async () => {
    const targetRef = isFullscreenReport ? fullscreenRef : dashboardRef;
    if (!targetRef.current) return;

    try {
      // Calculate dimensions of the target element
      const { width, height } = targetRef.current.getBoundingClientRect();

      // Override the style to match the calculated dimensions
      const style = {
        width: `${width}px`,
        height: `${height}px`,
