  onToggleVisibility: (domain: string) => void;
  onRemoveDomains: (domains: string[]) => void;
  onClearAll: () => void;
  lang: Language;
}

export const DomainManager: React.FC<DomainManagerProps> = ({
  visible,
  onClose,
  domainList,
  hiddenDomains,
  data,
  searchEngine,
  isCollecting,
  progress,
  onUpdateDomainList,
  onToggleVisibility,
  onRemoveDomains,
  onClearAll,
  lang
}) => {
  const [tab, setTab] = useState<'list' | 'text'>('list');
  const [bulkInputValue, setBulkInputValue] = useState(domainList.join('\n'));
  const [selectedDomains, setSelectedDomains] = useState<Set<string>>(new Set());
  const [domainSearch, setDomainSearch] = useState('');

  if (!visible) return null;
  const t = TRANSLATIONS[lang];

  const handleBulkTextSave = () => {
    const lines = bulkInputValue.split(/[\n,;\s]+/);
    const uniqueDomains = new Set<string>();
    lines.forEach(line => {
      const sanitized = sanitizeDomain(line);
      if (sanitized) uniqueDomains.add(sanitized);
    });
    const newDomainList = Array.from(uniqueDomains);
    onUpdateDomainList(newDomainList);
    setBulkInputValue('');
    onClose();
  };

  const toggleDomainSelection = (d: string) => {
    setSelectedDomains(prev => {
      const newSet = new Set(prev);
      if (newSet.has(d)) newSet.delete(d); else newSet.add(d);
      return newSet;
    });
  };

  const filteredDomainList = domainList.filter(d => d.includes(domainSearch.toLowerCase()));

  const selectAllFiltered = (filtered: string[]) => {
    const allSelected = filtered.every(d => selectedDomains.has(d));
    setSelectedDomains(prev => {
        const newSet = new Set(prev);
        if (allSelected) filtered.forEach(d => newSet.delete(d));
        else filtered.forEach(d => newSet.add(d));
        return newSet;
    });
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-2xl z-[300] flex items-center justify-center p-2 sm:p-8 animate-in fade-in duration-300">
      <div className="bg-white rounded-[1.5rem] lg:rounded-[3rem] w-full max-w-4xl h-[90vh] sm:h-auto sm:max-h-[90vh] shadow-[0_0_150px_rgba(0,0,0,0.4)] overflow-hidden flex flex-col animate-in zoom-in-95 duration-500 border border-slate-100">
        <div className="p-4 sm:p-6 lg:p-8 border-b border-slate-100 flex items-center justify-between bg-white z-10 shrink-0">
            <div className="flex flex-col gap-1">
                <div className="flex items-center gap-3 lg:gap-4"><Layers size={24} className="text-[#00a3ff] shrink-0 sm:w-7 sm:h-7" /><h3 className="text-2xl sm:text-3xl lg:text-4xl font-black text-[#1e293b] tracking-tight uppercase">{t.bulkAdd}</h3></div>
                <p className="text-slate-500 text-xs font-bold tracking-widest uppercase pl-9 sm:pl-10 lg:pl-12 hidden sm:block">Manage your competition set</p>
            </div>
            <button onClick={onClose} className="p-2.5 bg-slate-50 hover:bg-slate-100 rounded-2xl transition-colors text-slate-800 border border-slate-200 min-h-[44px] min-w-[44px] flex items-center justify-center"><X size={20} className="shrink-0" /></button>
        </div>
        <div className="px-3 sm:px-6 lg:px-10 py-3 lg:py-4 bg-slate-50 border-b border-slate-200 flex items-center gap-3 lg:gap-4 overflow-x-auto no-scrollbar shrink-0">
            <button onClick={() => { setTab('list'); setBulkInputValue(domainList.join('\n')); }} className={`flex items-center gap-2 lg:gap-3 px-4 sm:px-5 py-2 sm:py-2.5 rounded-xl text-[10px] sm:text-xs font-black tracking-widest uppercase transition-all whitespace-nowrap min-h-[36px] ${tab === 'list' ? 'bg-[#00a3ff] text-white shadow-lg' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-100'}`}><List size={14} className="shrink-0" /> {t.listView}</button>
            <button onClick={() => { setTab('text'); setBulkInputValue(domainList.join('\n')); }} className={`flex items-center gap-2 lg:gap-3 px-4 sm:px-5 py-2 sm:py-2.5 rounded-xl text-[10px] sm:text-xs font-black tracking-widest uppercase transition-all whitespace-nowrap min-h-[36px] ${tab === 'text' ? 'bg-[#00a3ff] text-white shadow-lg' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-100'}`}><Edit3 size={14} className="shrink-0" /> {t.textView}</button>
        </div>
        <div className="flex-1 overflow-hidden bg-slate-50/30 flex flex-col min-h-0 relative">
            {tab === 'list' && (
                <div className="flex flex-col h-full min-h-0">
                    <div className="px-4 sm:px-6 lg:px-10 py-4 lg:py-6 flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-100 bg-white/50 shrink-0">
                        <div className="relative flex-1 max-w-sm w-full">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 shrink-0" size={16} />
                            <input type="text" placeholder={t.searchDomains} value={domainSearch} onChange={(e) => setDomainSearch(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-2xl text-xs font-bold text-slate-800 focus:outline-none focus:border-[#00a3ff] focus:ring-4 focus:ring-[#00a3ff]/10 transition-all shadow-sm min-h-[40px]" />
                        </div>
                        <div className="flex items-center gap-3 self-end sm:self-auto overflow-x-auto max-w-full">
                            {filteredDomainList.length > 0 && <button onClick={() => selectAllFiltered(filteredDomainList)} className="px-4 py-2.5 text-[10px] font-bold text-slate-600 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-all flex items-center gap-2 uppercase tracking-wider whitespace-nowrap min-h-[36px]"><CheckSquare size={14} className="text-[#00a3ff] shrink-0" /> {filteredDomainList.every(d => selectedDomains.has(d)) ? 'Deselect All' : 'Select All'}</button>}
                            {domainList.length > 0 && <button onClick={onClearAll} className="px-4 py-2.5 text-[10px] font-bold text-rose-600 bg-rose-50 border border-rose-100 rounded-xl hover:bg-rose-100 transition-all flex items-center gap-2 uppercase tracking-wider whitespace-nowrap min-h-[36px]"><Trash2 size={14} className="shrink-0" /> {t.clearAll}</button>}
                        </div>
                    </div>
                    <div className="flex-1 overflow-y-auto custom-scrollbar p-4 sm:p-6 lg:p-10 overscroll-contain">
                        <div className="space-y-2 lg:space-y-3">
                            {filteredDomainList.length > 0 ? filteredDomainList.map(d => {
                                const isSelected = selectedDomains.has(d);
                                const isHidden = hiddenDomains.includes(d);
                                const health = getDomainHealth(d, data, searchEngine, isCollecting, progress);
                                return (
                                    <div key={d} onClick={() => toggleDomainSelection(d)} className={`flex items-center justify-between p-3 lg:p-4 rounded-2xl border transition-all cursor-pointer group select-none ${isSelected ? 'bg-blue-50 border-[#00a3ff] shadow-md' : 'bg-white border-slate-200 hover:border-blue-200 hover:shadow-sm'}`}>
                                        <div className="flex items-center gap-3 lg:gap-4 overflow-hidden">
                                            <div className={`w-6 h-6 rounded-lg border flex items-center justify-center transition-colors shrink-0 ${isSelected ? 'bg-[#00a3ff] border-[#00a3ff] text-white' : 'bg-white border-slate-300 text-transparent group-hover:border-[#00a3ff]'}`}><CheckSquare size={14} className="shrink-0" /></div>
                                            <div className="flex flex-col min-w-0">
                                                <span className={`text-sm lg:text-base font-bold truncate ${isSelected ? 'text-[#00a3ff]' : 'text-slate-700'} ${isHidden ? 'line-through opacity-50' : ''}`}>{d}</span>
                                                <div className="flex items-center gap-2 mt-0.5">
                                                    {health.status === 'error' && <div className="flex items-center gap-1 text-[9px] font-bold text-rose-600 bg-rose-50 px-1.5 py-0.5 rounded border border-rose-100"><XCircle size={10} /> {health.label}</div>}
                                                    {health.status === 'warning' && <div className="flex items-center gap-1 text-[9px] font-bold text-amber-600 bg-amber-50 px-1.5 py-0.5 rounded border border-amber-100"><AlertTriangle size={10} /> {health.label}</div>}
                                                    {health.status === 'ok' && <div className="flex items-center gap-1 text-[9px] font-bold text-emerald-600 bg-emerald-50 px-1.5 py-0.5 rounded border border-emerald-100"><CheckCircle2 size={10} /> {health.label}</div>}
                                                    {health.status === 'standby' && <div className="flex items-center gap-1 text-[9px] font-bold text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded border border-slate-200"><HelpCircle size={10} /> {health.label}</div>}
                                                    {isHidden && <div className="flex items-center gap-1 text-[9px] font-bold text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded border border-slate-200"><EyeOff size={10} /> Hidden</div>}
                                                </div>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-1 sm:gap-2">
                                            <button onClick={(e) => { e.stopPropagation(); onToggleVisibility(d); }} className={`p-2 rounded-xl transition-all min-h-[40px] min-w-[40px] flex items-center justify-center ${isHidden ? 'text-slate-400 bg-slate-50 hover:bg-slate-100' : 'text-[#00a3ff] hover:bg-blue-50'}`} title={isHidden ? "Show in reports" : "Hide from reports"}>{isHidden ? <EyeOff size={18} className="shrink-0" /> : <Eye size={18} className="shrink-0" />}</button>
                                            <button onClick={(e) => { e.stopPropagation(); onRemoveDomains([d]); }} className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all min-h-[40px] min-w-[40px] flex items-center justify-center" title="Delete domain"><Trash2 size={18} className="shrink-0" /></button>
                                        </div>
                                    </div>
                                );
                            }) : <div className="text-center py-20 text-slate-400 flex flex-col items-center"><Globe size={48} className="mb-4 opacity-20 shrink-0" /><p className="font-bold">{t.noDomainsFound}</p></div>}
                        </div>
                    </div>
                    {selectedDomains.size > 0 && <div className="p-4 sm:p-6 bg-white border-t border-slate-100 flex items-center justify-between animate-in slide-in-from-bottom-2 shrink-0"><span className="text-xs font-bold text-slate-600 uppercase tracking-wider pl-2">{selectedDomains.size} {t.selected}</span><button onClick={() => { onRemoveDomains(Array.from(selectedDomains)); setSelectedDomains(new Set()); }} className="px-6 py-2.5 bg-rose-500 text-white font-black rounded-xl shadow-lg hover:bg-rose-600 active:scale-95 transition-all flex items-center gap-2 uppercase tracking-widest text-[10px] min-h-[40px]"><Trash2 size={14} className="shrink-0" /> {t.deleteSelected}</button></div>}
                </div>
            )}
            {tab === 'text' && (
                <div className="flex flex-col h-full p-3 sm:p-6 lg:p-10">
                    <div className="mb-4 flex items-center gap-3 text-slate-500 shrink-0"><Info size={16} className="text-[#00a3ff] shrink-0" /><p className="text-[10px] font-bold uppercase tracking-wider">{t.textEditorDesc}</p></div>
                    <textarea value={bulkInputValue} onChange={(e) => setBulkInputValue(e.target.value)} className="flex-1 w-full bg-white border border-slate-200 rounded-[2rem] p-6 text-sm font-mono text-slate-800 focus:outline-none focus:border-[#00a3ff] focus:ring-4 focus:ring-[#00a3ff]/5 transition-all resize-none shadow-inner custom-textarea-scrollbar leading-relaxed" placeholder="example.com&#10;test.org" />
                    <div className="mt-4 sm:mt-6 flex justify-end shrink-0"><button onClick={handleBulkTextSave} className="px-8 py-3.5 bg-[#00a3ff] text-white font-black rounded-2xl shadow-xl hover:bg-[#0088d6] active:scale-95 transition-all flex items-center gap-2.5 uppercase tracking-widest text-xs min-h-[44px]"><Save size={18} className="shrink-0" /> {t.saveChanges}</button></div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  X, Layout, Target, Settings, RefreshCw, ShieldAlert,
  Layers, FileText, Sparkles, MapPin, Menu, Maximize2, Minimize2,
  Camera, EyeOff, Play, Globe, Square, Undo2, CheckCircle2
} from 'lucide-react';
// @ts-ignore
import { toBlob } from 'html-to-image';

import { DashboardData, VisualConfig } from './types';
import { fetchDomainData } from './services/serpstatApi';
import { MOCK_DATA } from './services/mockData';
import { HistoryComparisonChart, StackedPositionChart, NeuroComparisonChart, PagesComparisonChart } from './components/Charts';
import { DEFAULT_CONFIG, SEARCH_ENGINES, TRANSLATIONS, Language } from './constants';
import { getDomainHealth, isRegionMismatch, sanitizeDomain } from './utils';

import { NetpeakLogo, WarningsBanner, StandbyScreen } from './components/LayoutComponents';
import { SettingsModal, ApiConfigModal } from './components/Modals';
import { DomainManager } from './components/DomainManager';

interface UndoState {
  domainList: string[];
  hiddenDomains: string[];
  data: DashboardData | null;
  selectedDomains: Set<string>;
}

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>(() => (localStorage.getItem('netpeak_lang') as Language) || 'en');
  const [visualConfig, setVisualConfig] = useState<VisualConfig>(() => {
    const saved = localStorage.getItem('netpeak_visual_config');
    return saved ? JSON.parse(saved) : DEFAULT_CONFIG;
  });
  const [activeTab, setActiveTab] = useState('overview');
  const [metricType, setMetricType] = useState<'visible' | 'traff' | 'keywords'>('traff');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isFullscreenReport, setIsFullscreenReport] = useState(false);
  const [domainList, setDomainList] = useState<string[]>(() => JSON.parse(localStorage.getItem('netpeak_domains') || '[]'));
  const [hiddenDomains, setHiddenDomains] = useState<string[]>(() => JSON.parse(localStorage.getItem('netpeak_hidden_domains') || '[]'));

  // Modal States
  const [showDomainManager, setShowDomainManager] = useState(false);
  const [showVisualSettings, setShowVisualSettings] = useState(false);
  const [showApiConfig, setShowApiConfig] = useState(!localStorage.getItem('serpstat_key'));

  const [undoStack, setUndoStack] = useState<UndoState | null>(null);
  const [showUndoToast, setShowUndoToast] = useState(false);
  const undoTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [searchEngine, setSearchEngine] = useState(localStorage.getItem('serpstat_se') || 'g_us');
  const [data, setData] = useState<DashboardData | null>(() => JSON.parse(localStorage.getItem('netpeak_last_data') || 'null'));
  const [isCollecting, setIsCollecting] = useState(false);
  const [progress, setProgress] = useState<{current: string, percent: number} | null>(null);
  const [error, setError] = useState<{message: string, explanation: string} | null>(null);

  const [isScreenshotting, setIsScreenshotting] = useState(false);
  const [screenshotSuccess, setScreenshotSuccess] = useState(false);
  const fullscreenRef = useRef<HTMLDivElement>(null);
  const dashboardRef = useRef<HTMLDivElement>(null);
  const abortRef = useRef(false);

  const t = TRANSLATIONS[lang];

  useEffect(() => localStorage.setItem('netpeak_lang', lang), [lang]);
  useEffect(() => localStorage.setItem('netpeak_visual_config', JSON.stringify(visualConfig)), [visualConfig]);
  useEffect(() => localStorage.setItem('netpeak_domains', JSON.stringify(domainList)), [domainList]);
  useEffect(() => localStorage.setItem('netpeak_hidden_domains', JSON.stringify(hiddenDomains)), [hiddenDomains]);
  useEffect(() => localStorage.setItem('serpstat_se', searchEngine), [searchEngine]);
  useEffect(() => { if (data) localStorage.setItem('netpeak_last_data', JSON.stringify(data)) }, [data]);

  const updateVisualConfig = (key: keyof VisualConfig, value: any) => {
    setVisualConfig(prev => ({ ...prev, [key]: value }));
  };

  const filteredData = useMemo(() => {
    if (!data) return null;
    const result: DashboardData = {};
    let hasVisible = false;
    domainList.forEach(d => {
      if (!hiddenDomains.includes(d) && data[d]) {
        const health = getDomainHealth(d, data, searchEngine, isCollecting, progress);
        if (health.status !== 'error') {
           result[d] = data[d];
           hasVisible = true;
        }
      }
    });
    return hasVisible ? result : null;
  }, [data, hiddenDomains, searchEngine, domainList, isCollecting, progress]);

  const domainWarnings = useMemo(() => {
    const fractional: string[] = [];
    const excluded: string[] = [];
    const mismatched: string[] = [];
    domainList.forEach(d => {
      if (isRegionMismatch(d, searchEngine)) mismatched.push(d);
      else if (data) {
        const health = getDomainHealth(d, data, searchEngine, isCollecting, progress);
        if (health.status === 'warning' && health.label !== 'Region Mismatch') fractional.push(d);
        if (health.status === 'error') excluded.push(d);
      }
    });
    return { fractional, excluded, mismatched };
  }, [domainList, data, searchEngine, isCollecting, progress]);

  const runAnalysis = async () => {
    const currentKey = localStorage.getItem('serpstat_key');
    if (domainList.length === 0) return;
    if (!currentKey) { setShowApiConfig(true); return; }
    setError(null);
    setIsCollecting(true);
    abortRef.current = false;
    try {
      const newData: DashboardData = {}; 
      for (let i = 0; i < domainList.length; i++) {
        if (abortRef.current) {
          setError({ message: t.stopped, explanation: "User interrupted the analysis." });
          break;
        }
        const domain = domainList[i];
        setProgress({ current: domain, percent: Math.round((i / domainList.length) * 100) });
        try {
          const result = await fetchDomainData(domain, currentKey, searchEngine);
          newData[domain] = result;
        } catch (err: any) {
          if (err.message.includes('401')) throw new Error('401');
          console.warn(`Fetch error for ${domain}:`, err.message);
        }
      }
      setData(prev => (abortRef.current ? { ...prev, ...newData } : newData));
      setProgress(null);
    } catch (err: any) {
      if (err.message === '401') {
         setError({ message: t.authFailed, explanation: t.authFailedDesc });
         setShowApiConfig(true);
      } else setError({ message: "Analysis interrupted", explanation: err.message });
    } finally {
      setIsCollecting(false);
      abortRef.current = false;
    }
  };

  const saveStateForUndo = () => {
    setUndoStack({
      domainList: [...domainList],
      hiddenDomains: [...hiddenDomains],
      data: data ? JSON.parse(JSON.stringify(data)) : null,
      selectedDomains: new Set()
    });
    setShowUndoToast(true);
    if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
    undoTimeoutRef.current = setTimeout(() => {
      setShowUndoToast(false);
      setUndoStack(null);
    }, 6000);
  };

  const triggerUndo = () => {
    if (!undoStack) return;
    setDomainList(undoStack.domainList);
    setHiddenDomains(undoStack.hiddenDomains);
    setData(undoStack.data);
    setShowUndoToast(false);
    setUndoStack(null);
    if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
  };

  const handleScreenshot = async () => {
    const targetRef = isFullscreenReport ? fullscreenRef : dashboardRef;
    if (!targetRef.current) return;
    setIsScreenshotting(true);
    try {
      const isOriginal = !isFullscreenReport;

      const options = {
        quality: 1.0,
        pixelRatio: 3, 
        backgroundColor: '#ffffff', 
        cacheBust: true, 
        filter: (node: HTMLElement) => {
          if (node.tagName === 'LINK' && (node as HTMLLinkElement).rel === 'stylesheet') {
            const href = (node as HTMLLinkElement).href;
            return !(href && href.includes('fonts.googleapis.com'));
          }
          return true;
        }
      } as any;

      if (isOriginal) {
         // Original view: expand to fit full scrollable content
         options.style = { 
           transform: 'none', 
           height: 'auto', 
           maxHeight: 'none', 
           overflow: 'visible',
           border: 'none',
           borderRadius: '0',
           boxShadow: 'none',
         };
      } else {
         // Fullscreen view: Use offsetWidth/Height to include borders but crop strictly to the element
         options.width = targetRef.current.offsetWidth;
         options.height = targetRef.current.offsetHeight;
         options.style = {
           transform: 'none',
           borderRadius: 0,
           margin: 0,
           padding: 0, // Reset padding in style to avoid double padding if the lib adds it
           boxShadow: 'none',
         };
      }

      const blob = await toBlob(targetRef.current, options);
      if (!blob) throw new Error('Blob generation failed');
      await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
      setScreenshotSuccess(true);
      setTimeout(() => setScreenshotSuccess(false), 3000);
    } catch (e) {
      console.error('Screenshot failed', e);
    } finally {
      setIsScreenshotting(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#f8fafc] font-['Inter'] relative overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      {showUndoToast && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[500] animate-in slide-in-from-bottom-5 fade-in duration-300 w-[90%] sm:w-auto">
          <div className="bg-[#1e293b] text-white pl-6 pr-2 py-2 rounded-2xl shadow-2xl flex items-center gap-4 border border-slate-700/50 justify-between sm:justify-start">
            <span className="text-sm font-bold tracking-wide whitespace-nowrap">{t.deleted}</span>
            <div className="flex items-center gap-2">
              <button onClick={triggerUndo} className="px-4 py-2 bg-[#00a3ff] hover:bg-[#0088d6] text-white rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 min-h-[32px]"><Undo2 size={16} className="shrink-0" /> {t.undo}</button>
              <button onClick={() => setShowUndoToast(false)} className="p-2 text-slate-500 hover:text-white transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center"><X size={18} className="shrink-0" /></button>
            </div>
          </div>
        </div>
      )}

      {screenshotSuccess && (
        <div className="fixed top-10 left-1/2 -translate-x-1/2 z-[500] animate-in slide-in-from-top-5 fade-in duration-300">
           <div className="bg-emerald-500 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 border border-emerald-400"><CheckCircle2 size={20} className="shrink-0" /><span className="text-sm font-black tracking-wide uppercase">{t.screenshotCopied}</span></div>
        </div>
      )}

      {/* Sidebar */}
      <aside className={`w-[85%] sm:w-72 lg:w-56 xl:w-64 2xl:w-72 bg-white border-r border-slate-200 fixed lg:static h-full flex flex-col z-[70] transition-all duration-300 transform lg:transform-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-3 lg:p-4 flex flex-col h-full overflow-y-auto lg:overflow-hidden custom-scrollbar">
          <div className="flex items-center gap-3 lg:gap-4 mb-4 lg:mb-5 shrink-0 min-h-[44px]"><NetpeakLogo className="w-8 h-8 lg:w-8 lg:h-8 shrink-0" /><div className="flex flex-col"><span className="text-lg lg:text-base xl:text-lg font-black text-[#00A3FF] tracking-tight leading-none">Netpeak</span><span className="text-[9px] font-bold text-slate-500 tracking-[0.4em] mt-0.5 uppercase">Insights</span></div><button className="lg:hidden text-slate-400 ml-auto p-2 min-h-[44px] min-w-[44px] flex items-center justify-center" onClick={() => setIsSidebarOpen(false)}><X size={24} /></button></div>
          {isCollecting ? <button onClick={() => abortRef.current = true} className="w-full mb-2 flex items-center justify-center gap-3 py-3 lg:py-2.5 rounded-2xl text-[10px] lg:text-[11px] font-bold transition-all shadow-lg shrink-0 uppercase tracking-widest bg-rose-500 text-white hover:bg-rose-600 animate-pulse min-h-[44px]"><Square size={14} className="fill-current shrink-0" /> {t.stopReport}</button>
