import React, { useState, useEffect } from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  LabelList
} from 'recharts';
import { DashboardData, VisualConfig } from '../types';
import { THEMES, TRANSLATIONS } from '../constants';
import { formatNumber, getContrastColor } from '../utils';

const useChartDimensions = () => {
  const [dims, setDims] = useState({ 
    tooltip: 14,
    dotRadius: 4,
    dotActive: 6,
    strokeWidth: 3,
    margin: { top: 20, right: 30, left: 10, bottom: 40 },
    isLandscapeMobile: false
  });

  useEffect(() => {
    const update = () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const isLandscapeMobile = h < 500 && w > h;

      if (w >= 3000) { // ~4k
         setDims({ 
           tooltip: 32,
           dotRadius: 8,
           dotActive: 12,
           strokeWidth: 6,
           margin: { top: 40, right: 60, left: 20, bottom: 80 },
           isLandscapeMobile: false
         });
      } else if (w >= 2000) { // ~2k
         setDims({ 
           tooltip: 24,
           dotRadius: 6,
           dotActive: 9,
           strokeWidth: 4,
           margin: { top: 30, right: 40, left: 15, bottom: 60 },
           isLandscapeMobile: false
         });
      } else if (w >= 1536) { // Large Laptop
         setDims({ 
           tooltip: 16,
           dotRadius: 5,
           dotActive: 7,
           strokeWidth: 3,
           margin: { top: 20, right: 30, left: 10, bottom: 50 },
           isLandscapeMobile: false
         });
      } else if (isLandscapeMobile) {
         setDims({
           tooltip: 10,
           dotRadius: 3,
           dotActive: 5,
           strokeWidth: 2,
           margin: { top: 5, right: 20, left: 0, bottom: 20 },
           isLandscapeMobile: true
         });
      } else {
         setDims({ 
           tooltip: 14,
           dotRadius: 4,
           dotActive: 6,
           strokeWidth: 3,
           margin: { top: 20, right: 30, left: 10, bottom: 40 },
           isLandscapeMobile: false
         });
      }
    };
    window.addEventListener('resize', update);
    update();
    return () => window.removeEventListener('resize', update);
  }, []);
  return dims;
};

const ChartLegend = ({ items, iconType = 'circle', compact = false }: { items: any[], iconType?: 'circle' | 'rect', compact?: boolean }) => {
  if (!items || items.length === 0) return null;

  return (
    <div className={`flex flex-wrap justify-center items-center gap-x-3 sm:gap-x-6 ${compact ? 'gap-y-0 pb-1' : 'gap-y-1 sm:gap-y-3 pb-2 sm:pb-4'} px-2 sm:px-4 w-full border-b border-transparent shrink-0`}>
       {items.map((entry: any, index: number) => (
         <div key={`legend-item-${index}`} className="flex items-center min-w-0">
            <div 
               style={{ backgroundColor: entry.color }}
               className={`w-2.5 h-2.5 sm:w-4 sm:h-4 lg:w-5 lg:h-5 min-[2000px]:w-6 min-[2000px]:h-6 min-[3000px]:w-8 min-[3000px]:h-8 mr-1.5 sm:mr-3 shrink-0 border border-slate-200 ${iconType === 'circle' ? 'rounded-full' : 'rounded-[2px]'}`}
            />
            <span className={`font-bold text-slate-700 leading-tight whitespace-nowrap ${compact ? 'text-[9px]' : 'text-[10px] sm:text-sm lg:text-lg 2xl:text-xl min-[2000px]:text-2xl min-[3000px]:text-4xl'}`}>
               {entry.value}
            </span>
         </div>
       ))}
    </div>
  );
};

const CustomTooltip = ({ active, payload, label, dims, lang }: any) => {
  if (active && payload && payload.length) {
    return (
      <div style={{
        backgroundColor: 'rgba(255, 255, 255, 0.96)',
        border: '1px solid #e2e8f0',
        borderRadius: dims.isLandscapeMobile ? '8px' : '16px',
        padding: dims.isLandscapeMobile ? '8px' : '16px',
        boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)',
        fontSize: `${dims.tooltip}px`,
        fontWeight: '700',
        color: '#1e293b'
      }}>
        <p className={`border-b border-slate-100 ${dims.isLandscapeMobile ? 'mb-1 pb-1' : 'mb-2 pb-2'}`}>{label}</p>
        {payload.map((entry: any, index: number) => (
          <div key={index} style={{ color: entry.color || entry.fill }} className="flex items-center gap-2 mb-1">
            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color || entry.fill }}></span>
            <span>{entry.name}: {formatNumber(entry.value, lang)}</span>
          </div>
        ))}
      </div>
    );
  }
  return null;
};

const CHART_LABELS = {
  en: { aioKeywords: 'Phrases with AI answers', domainInAio: 'Domain in AI answers', pages: 'Total Indexed Pages' },
  ua: { aioKeywords: 'Фрази з AI відповідями', domainInAio: 'Домен в AI відповідях', pages: 'Проіндексовані сторінки' }
};

export const HistoryComparisonChart: React.FC<{ 
  data: DashboardData, 
  metric: 'visible' | 'traff' | 'keywords', 
  lang: 'en' | 'ua', 
  config: VisualConfig
}> = ({ data, metric, lang, config }) => {
  const domains = Object.keys(data);
  const dims = useChartDimensions();
  if (domains.length === 0) return null;
  const colors = THEMES[config.style].line;

  const allMonths = Array.from(new Set(domains.flatMap(d => 
    data[d].history.map(h => h.date.substring(0, 7))
  ))).sort();

  const chartData = allMonths.map(monthStr => {
    const entry: any = { month: monthStr };
    domains.forEach(d => {
      const monthItems = data[d].history.filter(h => h.date.startsWith(monthStr));
      if (monthItems.length > 0) {
        const latest = monthItems.sort((a, b) => b.date.localeCompare(a.date))[0];
        entry[d] = latest[metric];
      } else {
        entry[d] = null;
      }
    });
    return entry;
  });

  const sortedDomains = domains;
  const legendItems = sortedDomains.map((d, i) => ({
    value: d,
    color: colors[i % colors.length]
  }));

  const axisFontSize = dims.isLandscapeMobile ? 9 : config.axisFontSize;
  const axisHeight = dims.isLandscapeMobile ? 24 : config.axisFontSize * 4;
  const axisDy = dims.isLandscapeMobile ? 5 : 10;

  return (
    <div className="w-full h-full flex flex-col">
      <ChartLegend items={legendItems} iconType="circle" compact={dims.isLandscapeMobile} />
      <div className="flex-1 min-h-0 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={chartData} margin={dims.margin}>
            <CartesianGrid vertical={false} stroke="#e2e8f0" strokeDasharray="3 3" />
            <XAxis 
              dataKey="month" 
              interval="preserveStartEnd"
              padding={{ left: 20, right: 20 }}
              stroke="#64748b" 
              fontSize={axisFontSize} 
              fontWeight="600"
              tickLine={false} 
              axisLine={false} 
              dy={axisDy}
              height={axisHeight}
              tickFormatter={(str) => { 
                const [y, m] = str.split('-'); 
                return `${parseInt(m).toString().padStart(2, '0')}.${y.substring(2)}`; 
              }} 
            />
            <YAxis 
              stroke="#64748b" 
              fontSize={axisFontSize} 
              fontWeight="600" 
              tickLine={false} 
              axisLine={false}
              width={axisFontSize * 4.5}
              tickFormatter={(v) => formatNumber(v, lang)} 
            />
            <Tooltip content={<CustomTooltip dims={dims} lang={lang} />} />
            {sortedDomains.map((d, i) => (
              <Line 
                key={d} 
                name={d} 
                type="monotone" 
                dataKey={d} 
                stroke={colors[i % colors.length]} 
                strokeWidth={dims.strokeWidth} 
                dot={{ r: dims.dotRadius, strokeWidth: Math.max(1, dims.strokeWidth - 2), fill: colors[i % colors.length], stroke: 'white' }} 
                activeDot={{ r: dims.dotActive, strokeWidth: dims.strokeWidth, stroke: 'white' }} 
                connectNulls 
                isAnimationActive={true}
                animationDuration={1500}
              >
