import { DashboardData } from './types';

export const sanitizeDomain = (url: string): string => {
  if (!url) return '';
  let domain = url.toLowerCase().trim();
  if (domain.includes('://')) domain = domain.split('://')[1];
  domain = domain.split('/')[0]; // Remove paths
  domain = domain.replace(/^www\./, '');
  domain = domain.replace(/[;,.,]+$/, '');
  return domain;
};

export const isRegionMismatch = (domain: string, region: string): boolean => {
  const d = domain.toLowerCase();
  if ((d.endsWith('.ua') || d.endsWith('.com.ua')) && region !== 'g_ua') return true;
  if ((d.endsWith('.uk') || d.endsWith('.co.uk')) && region !== 'g_uk') return true;
  if (d.endsWith('.de') && region !== 'g_de') return true;
  if (d.endsWith('.fr') && region !== 'g_fr') return true;
  if (d.endsWith('.es') && region !== 'g_es') return true;
  if (d.endsWith('.it') && region !== 'g_it') return true;
  if (d.endsWith('.pl') && region !== 'g_pl') return true;
  if (d.endsWith('.kz') && region !== 'g_kz') return true;
  return false;
};

export const formatNumber = (num: number, lang: 'en' | 'ua') => {
  return num.toLocaleString(lang === 'ua' ? 'ru-RU' : 'en-US').replace(/,/g, lang === 'ua' ? ' ' : ',');
};

export const formatCompactNumber = (num: number, lang: 'en' | 'ua') => {
  try {
    return new Intl.NumberFormat(lang === 'ua' ? 'ru-RU' : 'en-US', {
      notation: "compact",
      compactDisplay: "short",
      maximumFractionDigits: 1
    }).format(num);
  } catch (e) {
    return formatNumber(num, lang);
  }
};

export const getContrastColor = (hexColor: string) => {
  if (!hexColor) return '#1e293b';
  const hex = hexColor.replace('#', '');
  const r = parseInt(hex.substr(0, 2), 16);
  const g = parseInt(hex.substr(2, 2), 16);
  const b = parseInt(hex.substr(4, 2), 16);
  const yiq = ((r * 299) + (g * 587) + (b * 114)) / 1000;
  return yiq >= 128 ? '#1e293b' : '#FFFFFF'; 
};

export type DomainHealthStatus = 'ok' | 'warning' | 'error' | 'standby' | 'loading';

export const getDomainHealth = (
  domain: string,
  data: DashboardData | null,
  searchEngine: string,
  isCollecting: boolean,
  progress: { current: string; percent: number } | null
): { status: DomainHealthStatus; label: string; color: string } => {
  if (isCollecting && progress?.current === domain) return { status: 'loading', label: 'Analyzing...', color: 'bg-blue-400 animate-pulse' };
  if (isRegionMismatch(domain, searchEngine)) return { status: 'warning', label: 'Region Mismatch', color: 'bg-amber-400' };
  if (!data || !data[domain]) return { status: 'standby', label: 'Standby', color: 'bg-slate-300' };
  const entry = data[domain];
  if (!entry) return { status: 'error', label: 'No Data / Excluded', color: 'bg-rose-400' };
  const historyPoints = entry.history?.length || 0;
  const totalTraffic = entry.history?.reduce((a, b) => a + b.traff, 0) || 0;
  if (historyPoints === 0) return { status: 'error', label: 'Insufficient Data', color: 'bg-rose-400' };
  if (historyPoints < 3 || totalTraffic === 0) return { status: 'warning', label: 'Fractional Data', color: 'bg-orange-400' };
  return { status: 'ok', label: 'Ready', color: 'bg-emerald-400' };
};

import React, { useState, useEffect } from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  LabelList
} from 'recharts';
