                      {activeTab === 'overview' ? (metricType === 'traff' ? t.trendTitle : metricType === 'visible' ? t.visibilityTitle : t.keywordsTitle) : (activeTab === 'rankings' ? t.serpTitle : activeTab === 'ai-overview' ? t.aioTitle : t.indexTitle)}
                    </h3>
                    {!isLandscapeMobile && <div className={`mt-1 transition-opacity duration-300 ${visualConfig.showSource ? 'opacity-100' : 'opacity-0 h-0 overflow-hidden'}`}><span className="text-[9px] font-bold text-slate-300 opacity-60 tracking-[0.5em] uppercase">{t.dataSource}</span></div>}
                  </div>
                  <div className={`flex-1 ${isLandscapeMobile ? 'p-0 pb-1' : 'p-2 sm:p-4 lg:p-4'} min-h-0 relative overflow-hidden flex flex-col`}>
                    <div className="flex-1 w-full h-full min-h-0">
                      {activeTab === 'overview' && <HistoryComparisonChart data={filteredData} metric={metricType} lang={lang} config={visualConfig} />}
