          <div className="flex-1 p-2 sm:p-4 md:p-8 flex items-center justify-center bg-[#ffffff] overflow-hidden min-h-0 h-full">
             <div ref={fullscreenRef} className="w-full h-full max-w-[1920px] bg-white rounded-none sm:rounded-[2rem] border-none sm:border sm:border-slate-100 shadow-none sm:shadow-2xl p-4 sm:p-8 relative overflow-hidden flex flex-col min-h-0">
                <div className="shrink-0 p-2 sm:p-4 flex flex-col items-center text-center"><h3 className="font-black tracking-tighter text-[#00A3FF] mb-2 leading-tight" style={{ fontSize: `${visualConfig.headerFontSize}px` }}>{activeTab === 'overview' ? (metricType === 'traff' ? t.trendTitle : metricType === 'visible' ? t.visibilityTitle : t.keywordsTitle) : (activeTab === 'rankings' ? t.serpTitle : activeTab === 'ai-overview' ? t.aioTitle : t.indexTitle)}</h3></div>
                <div className="flex-1 min-h-0 relative w-full h-full flex flex-col">
                  <div className="flex-1 w-full h-full min-h-0">
                    {activeTab === 'overview' && <HistoryComparisonChart data={filteredData} metric={metricType} lang={lang} config={visualConfig} logScale={isLogScale} />}
                    {activeTab === 'rankings' && <StackedPositionChart data={filteredData} lang={lang} config={visualConfig} mode={rankingMode} />}
                    {activeTab === 'ai-overview' && <NeuroComparisonChart data={filteredData} lang={lang} config={visualConfig} />}
                    {activeTab === 'index' && <PagesComparisonChart data={filteredData} lang={lang} config={visualConfig} />}
                  </div>
                </div>
                <div className={`absolute bottom-4 right-8 transition-opacity duration-300 pointer-events-none ${visualConfig.showSource ? 'opacity-40' : 'opacity-0'}`}><span className="text-[9px] font-bold text-slate-400 tracking-[0.5em] uppercase">{t.dataSource}</span></div>
             </div>
          </div>
        </div>
      )}

      {/* Modals */}
      <SettingsModal 
        visible={showVisualSettings} 
        onClose={() => setShowVisualSettings(false)} 
        config={visualConfig} 
        onUpdateConfig={updateVisualConfig} 
        onLoadDemo={() => { saveStateForUndo(); setData(MOCK_DATA); setDomainList(Object.keys(MOCK_DATA)); setHiddenDomains([]); }} 
        lang={lang} 
      />

      <ApiConfigModal 
        visible={showApiConfig} 
        onClose={() => setShowApiConfig(false)} 
        lang={lang} 
      />

      <DomainManager 
        visible={showDomainManager} 
        onClose={() => setShowDomainManager(false)} 
        domainList={domainList}
        hiddenDomains={hiddenDomains}
        data={data}
        searchEngine={searchEngine}
        isCollecting={isCollecting}
        progress={progress}
        onUpdateDomainList={(newList) => {
            const toRemove = domainList.filter(d => !newList.includes(d));
            if (toRemove.length > 0) saveStateForUndo();
            setDomainList(newList);
            if (toRemove.length > 0) {
              setData(prev => {
                if (!prev) return null;
                const next = { ...prev };
                toRemove.forEach(d => delete next[d]);
                return Object.keys(next).length > 0 ? next : null;
              });
            }
        }}
        onToggleVisibility={(d) => setHiddenDomains(prev => prev.includes(d) ? prev.filter(x => x !== d) : [...prev, d])}
        onRemoveDomains={(domainsToRemove) => {
            saveStateForUndo();
            setDomainList(prev => prev.filter(d => !domainsToRemove.includes(d)));
            setHiddenDomains(prev => prev.filter(d => !domainsToRemove.includes(d)));
            setData(prevData => {
                if (!prevData) return null;
                const newData = { ...prevData };
                domainsToRemove.forEach(d => delete newData[d]);
                return Object.keys(newData).length > 0 ? newData : null;
            });
        }}
        onClearAll={() => {
            saveStateForUndo();
            setDomainList([]);
            setHiddenDomains([]);
            setData(null);
            localStorage.removeItem('netpeak_last_data');
        }}
        lang={lang}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  LabelList
} from 'recharts';
import { DashboardData, VisualConfig, PositionRange } from '../types';
import { THEMES, TRANSLATIONS } from '../constants';
import { formatNumber, formatCompactNumber, getContrastColor } from '../utils';

const useChartDimensions = () => {
  const [dims, setDims] = useState({ 
    tooltip: 14,
    dotRadius: 4,
    dotActive: 6,
    strokeWidth: 3,
    margin: { top: 20, right: 30, left: 10, bottom: 40 },
    isLandscapeMobile: false
  });

  useEffect(() => {
    const update = () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      const isLandscapeMobile = h < 500 && w > h;

      if (w >= 3000) { // ~4k
         setDims({ 
           tooltip: 32,
           dotRadius: 8,
           dotActive: 12,
           strokeWidth: 6,
           margin: { top: 40, right: 60, left: 20, bottom: 80 },
           isLandscapeMobile: false
         });
      } else if (w >= 2000) { // ~2k
         setDims({ 
           tooltip: 24,
           dotRadius: 6,
           dotActive: 9,
           strokeWidth: 4,
           margin: { top: 30, right: 40, left: 15, bottom: 60 },
           isLandscapeMobile: false
         });
      } else if (w >= 1536) { // Large Laptop
         setDims({ 
           tooltip: 16,
           dotRadius: 5,
           dotActive: 7,
           strokeWidth: 3,
           margin: { top: 20, right: 30, left: 10, bottom: 50 },
           isLandscapeMobile: false
         });
      } else if (isLandscapeMobile) {
         setDims({
           tooltip: 10,
           dotRadius: 3,
           dotActive: 5,
           strokeWidth: 2,
           margin: { top: 5, right: 40, left: 10, bottom: 20 },
           isLandscapeMobile: true
         });
      } else {
         setDims({ 
           tooltip: 14,
           dotRadius: 4,
           dotActive: 6,
           strokeWidth: 3,
           margin: { top: 20, right: 30, left: 10, bottom: 40 },
           isLandscapeMobile: false
         });
      }
    };
    window.addEventListener('resize', update);
    update();
    return () => window.removeEventListener('resize', update);
  }, []);
  return dims;
};

const ChartLegend = ({ items, iconType = 'circle', compact = false }: { items: any[], iconType?: 'circle' | 'rect', compact?: boolean }) => {
  if (!items || items.length === 0) return null;

  return (
    <div className={`flex flex-wrap justify-center items-center gap-x-3 sm:gap-x-6 ${compact ? 'gap-y-0 pb-1' : 'gap-y-1 sm:gap-y-3 pb-2 sm:pb-4'} px-2 sm:px-4 w-full border-b border-transparent shrink-0`}>
       {items.map((entry: any, index: number) => (
         <div key={`legend-item-${index}`} className="flex items-center min-w-0">
            <div 
               style={{ backgroundColor: entry.color }}
               className={`w-2.5 h-2.5 sm:w-4 sm:h-4 lg:w-5 lg:h-5 min-[2000px]:w-6 min-[2000px]:h-6 min-[3000px]:w-8 min-[3000px]:h-8 mr-1.5 sm:mr-3 shrink-0 border border-slate-200 ${iconType === 'circle' ? 'rounded-full' : 'rounded-[2px]'}`}
            />
            <span className={`font-bold text-slate-700 leading-tight whitespace-nowrap ${compact ? 'text-[9px]' : 'text-[10px] sm:text-sm lg:text-lg 2xl:text-xl min-[2000px]:text-2xl min-[3000px]:text-4xl'}`}>
               {entry.value}
            </span>
         </div>
       ))}
    </div>
  );
};

const CustomTooltip = ({ active, payload, label, dims, lang }: any) => {
  if (active && payload && payload.length) {
    return (
      <div style={{
        backgroundColor: 'rgba(255, 255, 255, 0.96)',
        border: '1px solid #e2e8f0',
        borderRadius: dims.isLandscapeMobile ? '8px' : '16px',
        padding: dims.isLandscapeMobile ? '8px' : '16px',
        boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)',
        fontSize: `${dims.tooltip}px`,
        fontWeight: '700',
        color: '#1e293b'
      }}>
        <p className={`border-b border-slate-100 ${dims.isLandscapeMobile ? 'mb-1 pb-1' : 'mb-2 pb-2'}`}>{label}</p>
        {payload.map((entry: any, index: number) => (
          <div key={index} style={{ color: entry.color || entry.fill }} className="flex items-center gap-2 mb-1">
            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color || entry.fill }}></span>
            <span>{entry.name}: {formatNumber(entry.value, lang)}</span>
          </div>
        ))}
      </div>
    );
  }
  return null;
};

const CHART_LABELS = {
  en: { aioKeywords: 'Phrases with AI answers', domainInAio: 'Domain in AI answers', pages: 'Total Indexed Pages' },
  ua: { aioKeywords: 'Фрази з AI відповідями', domainInAio: 'Домен в AI відповідях', pages: 'Проіндексовані сторінки' }
};

export const HistoryComparisonChart: React.FC<{ 
  data: DashboardData, 
  metric: 'visible' | 'traff' | 'keywords', 
  lang: 'en' | 'ua', 
  config: VisualConfig,
  logScale?: boolean
}> = ({ data, metric, lang, config, logScale = false }) => {
  const domains = Object.keys(data);
  const dims = useChartDimensions();
  if (domains.length === 0) return null;
  const colors = THEMES[config.style].line;

  const allMonths = Array.from(new Set(domains.flatMap(d => 
    data[d].history.map(h => h.date.substring(0, 7))
  ))).sort();

  const chartData = allMonths.map(monthStr => {
    const entry: any = { month: monthStr };
    domains.forEach(d => {
      const monthItems = data[d].history.filter(h => h.date.startsWith(monthStr));
      if (monthItems.length > 0) {
        const latest = monthItems.sort((a, b) => b.date.localeCompare(a.date))[0];
        entry[d] = latest[metric];
      } else {
        entry[d] = null;
      }
    });
    return entry;
  });

  const sortedDomains = domains;
  const legendItems = sortedDomains.map((d, i) => ({
    value: d,
    color: colors[i % colors.length]
  }));

  const axisFontSize = dims.isLandscapeMobile ? 9 : config.axisFontSize;
  const axisHeight = dims.isLandscapeMobile ? 24 : config.axisFontSize * 4;
  const axisDy = dims.isLandscapeMobile ? 5 : 10;
  // Use a compact width for mobile landscape to fit within the screen while showing compact numbers
  const yAxisWidth = dims.isLandscapeMobile ? 35 : config.axisFontSize * 4.5;

  return (
    <div className="w-full h-full flex flex-col">
      <ChartLegend items={legendItems} iconType="circle" compact={dims.isLandscapeMobile} />
      <div className="flex-1 min-h-0 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={chartData} margin={dims.margin}>
            <CartesianGrid vertical={false} stroke="#e2e8f0" strokeDasharray="3 3" />
            <XAxis 
              dataKey="month" 
              interval="preserveStartEnd"
              padding={{ left: 20, right: 20 }}
              stroke="#64748b" 
              fontSize={axisFontSize} 
              fontWeight="600"
              tickLine={false} 
              axisLine={false} 
              dy={axisDy}
              height={axisHeight}
              tickFormatter={(str) => { 
                const [y, m] = str.split('-'); 
                return `${parseInt(m).toString().padStart(2, '0')}.${y.substring(2)}`; 
              }} 
            />
            <YAxis 
              scale={logScale ? "log" : "auto"}
              domain={logScale ? ['auto', 'auto'] : [0, 'auto']}
              allowDataOverflow={true}
              stroke="#64748b" 
              fontSize={axisFontSize} 
              fontWeight="600" 
              tickLine={false} 
              axisLine={false}
              width={yAxisWidth}
              tickFormatter={(v) => formatCompactNumber(v, lang)} 
            />
            <Tooltip content={<CustomTooltip dims={dims} lang={lang} />} />
            {sortedDomains.map((d, i) => (
              <Line 
                key={d} 
                name={d} 
                type="monotone" 
                dataKey={d} 
                stroke={colors[i % colors.length]} 
                strokeWidth={dims.strokeWidth} 
                dot={{ r: dims.dotRadius, strokeWidth: Math.max(1, dims.strokeWidth - 2), fill: colors[i % colors.length], stroke: 'white' }} 
                activeDot={{ r: dims.dotActive, strokeWidth: dims.strokeWidth, stroke: 'white' }} 
                connectNulls 
                isAnimationActive={false}
              >
                {config.showValues && (
                  <LabelList 
                    dataKey={d} 
                    position="top" 
                    offset={10 + config.labelOffset} 
                    fontSize={config.labelFontSize} 
                    fontWeight="700" 
                    fill={colors[i % colors.length]} 
                    formatter={(v: any) => v ? formatCompactNumber(v, lang) : ''} 
                  />
                )}
              </Line>
            ))}
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export const StackedPositionChart: React.FC<{ 
  data: DashboardData, 
  lang: 'en' | 'ua',
  config: VisualConfig,
  mode?: 'domain' | 'range'
}> = ({ data, lang, config, mode = 'range' }) => {
  const domains = Object.keys(data);
  const dims = useChartDimensions();
  const stackColors = THEMES[config.style].stack;
  const domainColors = THEMES[config.style].line;

  let chartData: any[] = [];
  let seriesKeys: any[] = [];
  let isPercent = false;

  if (mode === 'domain') {
    chartData = domains.map(d => {
      const p = data[d].positions;
      const total = p.range1 + p.range2_3 + p.range4_10 + p.range11_20 + p.range21_50 + p.range51_100;
      return {
        name: d,
        total,
        range1: p.range1,
        range2_3: p.range2_3,
        range4_10: p.range4_10,
        range11_20: p.range11_20,
        range21_50: p.range21_50,
        range51_100: p.range51_100,
      };
    }).sort((a, b) => b.total - a.total); 

    seriesKeys = [
      { key: 'range1', name: '1', color: stackColors[0] },
      { key: 'range2_3', name: '2 - 3', color: stackColors[1] },
      { key: 'range4_10', name: '4 - 10', color: stackColors[2] },
      { key: 'range11_20', name: '11 - 20', color: stackColors[3] },
      { key: 'range21_50', name: '21 - 50', color: stackColors[4] },
      { key: 'range51_100', name: '51 - 100', color: stackColors[5] },
    ];
  } else {
    isPercent = true;
    const rangeKeys = ['range1', 'range2_3', 'range4_10', 'range11_20', 'range21_100'];
    const rangeNames = {
      'range1': 'Top-1',
      'range2_3': 'Top-2-3',
      'range4_10': 'Top-4-10',
      'range11_20': 'Top-11-20',
      'range21_100': 'Top-21-100'
    };

    chartData = rangeKeys.map(rKey => {
      const item: any = { name: rangeNames[rKey as keyof typeof rangeNames] };
      domains.forEach(d => {
        let val = 0;
        if (rKey === 'range21_100') {
           val = data[d].positions.range21_50 + data[d].positions.range51_100;
        } else {
           val = data[d].positions[rKey as keyof PositionRange] as number;
        }
        item[d] = val;
      });
      return item;
    });

    seriesKeys = domains.map((d, i) => ({
      key: d,
      name: d,
      color: domainColors[i % domainColors.length]
    }));
  }

  const legendItems = seriesKeys.map(s => ({ value: s.name, color: s.color }));

  const axisFontSize = dims.isLandscapeMobile ? 9 : config.axisFontSize;
  const axisHeight = dims.isLandscapeMobile ? 30 : config.axisFontSize * 8;
  const axisDy = dims.isLandscapeMobile ? 5 : 15;
  const yAxisWidth = dims.isLandscapeMobile ? 35 : config.axisFontSize * 4.5;

  return (
    <div className="w-full h-full flex flex-col">
      <ChartLegend items={legendItems} iconType="rect" compact={dims.isLandscapeMobile} />
      <div className="flex-1 min-h-0 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={chartData} margin={dims.margin} stackOffset={isPercent ? "expand" : "none"}>
            <CartesianGrid vertical={false} stroke="#e2e8f0" strokeDasharray="3 3" />
            <XAxis 
              dataKey="name" 
              stroke="#1e293b" 
              fontSize={axisFontSize} 
              fontWeight="700" 
              tickLine={false} 
              axisLine={false} 
              dy={axisDy}
              angle={dims.isLandscapeMobile ? 0 : -35} 
              textAnchor={dims.isLandscapeMobile ? "middle" : "end"}
              interval={0}
              height={axisHeight}
            />
            <YAxis 
              stroke="#64748b" 
              fontSize={axisFontSize} 
              fontWeight="600" 
              tickLine={false} 
              axisLine={false} 
              width={yAxisWidth} 
              tickFormatter={(v) => isPercent ? `${(v * 100).toFixed(0)}%` : formatCompactNumber(v, lang)} 
            />
            <Tooltip content={<CustomTooltip dims={dims} lang={lang} />} cursor={{fill: '#f1f5f9', opacity: 0.5}} />
            {seriesKeys.map((s, idx) => (
              <Bar 
                key={s.key}
                name={s.name} 
                dataKey={s.key} 
                stackId="distribution" 
                fill={s.color} 
                isAnimationActive={false} 
                radius={idx === seriesKeys.length - 1 ? [6, 6, 0, 0] : [0, 0, 0, 0]} 
              >
                 {config.showValues && (
                   <LabelList 
                      dataKey={s.key} 
                      position="inside"
                      dy={config.labelOffset}
                      fill={getContrastColor(s.color)} 
                      fontSize={config.labelFontSize} 
                      fontWeight="700" 
                      formatter={(v: number) => {
                         if (!v || v <= 0) return '';
                         if (isPercent) return formatCompactNumber(v, lang); // Always show absolute value even in percent mode
                         if (v < 3) return ''; 
                         return formatCompactNumber(v, lang);
                      }} 
                   />
                 )}
              </Bar>
            ))}
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

