              type="password" 
              value={password}
              onChange={(e) => { setPassword(e.target.value); setError(false); }}
              placeholder={t.password}
              className={`w-full bg-slate-50 border ${error ? 'border-rose-300 ring-4 ring-rose-100' : 'border-slate-200 focus:border-[#00a3ff] focus:ring-4 focus:ring-[#00a3ff]/10'} rounded-xl px-4 py-3.5 font-bold text-slate-800 outline-none transition-all placeholder:text-slate-400`}
