const App: React.FC = () => {
  const [lang, setLang] = useState<Language>(() => (localStorage.getItem('netpeak_lang') as Language) || 'en');
  const [visualConfig, setVisualConfig] = useState<VisualConfig>(() => {
    const saved = localStorage.getItem('netpeak_visual_config');
    return saved ? JSON.parse(saved) : DEFAULT_CONFIG;
  });
  const [activeTab, setActiveTab] = useState('overview');
  const [metricType, setMetricType] = useState<'visible' | 'traff' | 'keywords'>('traff');
  const [rankingMode, setRankingMode] = useState<'domain' | 'range'>('range');
  const [isLogScale, setIsLogScale] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isFullscreenReport, setIsFullscreenReport] = useState(false);
  const [domainList, setDomainList] = useState<string[]>(() => JSON.parse(localStorage.getItem('netpeak_domains') || '[]'));
  const [hiddenDomains, setHiddenDomains] = useState<string[]>(() => JSON.parse(localStorage.getItem('netpeak_hidden_domains') || '[]'));

  // Modal States
  const [showDomainManager, setShowDomainManager] = useState(false);
  const [showVisualSettings, setShowVisualSettings] = useState(false);
  const [showApiConfig, setShowApiConfig] = useState(false); // Initially false, checked in useEffect

  const [undoStack, setUndoStack] = useState<UndoState | null>(null);
  const [showUndoToast, setShowUndoToast] = useState(false);
  const undoTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [searchEngine, setSearchEngine] = useState(localStorage.getItem('serpstat_se') || 'g_us');
  const [data, setData] = useState<DashboardData | null>(() => JSON.parse(localStorage.getItem('netpeak_last_data') || 'null'));
  const [isCollecting, setIsCollecting] = useState(false);
  const [progress, setProgress] = useState<{current: string, percent: number} | null>(null);
  const [error, setError] = useState<{message: string, explanation: string} | null>(null);

  const [isScreenshotting, setIsScreenshotting] = useState(false);
  const [screenshotSuccess, setScreenshotSuccess] = useState(false);
  const fullscreenRef = useRef<HTMLDivElement>(null);
  const dashboardRef = useRef<HTMLDivElement>(null);
  const abortRef = useRef(false);

  // Snapshot / Read Only Logic
  const [viewMode, setViewMode] = useState<'live' | 'snapshot-locked' | 'snapshot-view'>('live');
  const [snapshotId, setSnapshotId] = useState<string | null>(null);
  const [snapshotHasOAuth, setSnapshotHasOAuth] = useState(false);

  // Responsive state for landscape mobile
  const [isLandscapeMobile, setIsLandscapeMobile] = useState(false);

  useEffect(() => {
    // 1. Check for API Key on mount (only for live mode)
    if (!localStorage.getItem('serpstat_key') && window.location.pathname.indexOf('/report/') === -1) {
      setShowApiConfig(true);
    }

    // 2. Check for Snapshot URL
    const path = window.location.pathname;
    const match = path.match(/\/report\/([a-zA-Z0-9-]+)/);

    // Check for Auth Token in URL (From Google Redirect)
    const urlParams = new URLSearchParams(window.location.search);
    const authToken = urlParams.get('token');

    if (match && match[1]) {
      const sId = match[1];
      setSnapshotId(sId);

      if (authToken) {
          // If we have a token, try to unlock immediately
          unlockSnapshot(sId, '', authToken);
          // Remove token from URL to clean up
          window.history.replaceState({}, document.title, `/presale-helper/report/${sId}`);
      } else {
          setViewMode('snapshot-locked');
          // Check status to see if public or needs auth methods
          fetch(`/presale-helper/api/snapshot/${sId}/status`)
            .then(res => res.json())
            .then(status => {
               if (!status.isLocked) {
                  unlockSnapshot(sId, '');
               } else {
                  setSnapshotHasOAuth(status.authMethods?.oauth || false);
               }
            })
            .catch(err => console.error(err));
      }
    }
  }, []);

  const unlockSnapshot = async (id: string, password: string, authToken?: string) => {
    try {
      const res = await fetch(`/presale-helper/api/snapshot/${id}/unlock`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password, authToken })
      });
      if (res.status === 403) return false;
      if (!res.ok) throw new Error('Failed to load');
      const json = await res.json();

      // Load data
      setData(json.data);
      setDomainList(json.domainList);
      setHiddenDomains([]);
      setViewMode('snapshot-view');
      return true;
    } catch (e) {
      return false;
    }
  };

  useEffect(() => {
    const checkOrientation = () => {
      // Check if height is small (typical mobile landscape is < 500px) and width is larger than height
      setIsLandscapeMobile(window.innerHeight < 500 && window.innerWidth > window.innerHeight);
    };
    window.addEventListener('resize', checkOrientation);
    checkOrientation();
    return () => window.removeEventListener('resize', checkOrientation);
  }, []);

  const t = TRANSLATIONS[lang];

  useEffect(() => localStorage.setItem('netpeak_lang', lang), [lang]);
  useEffect(() => localStorage.setItem('netpeak_visual_config', JSON.stringify(visualConfig)), [visualConfig]);
  useEffect(() => localStorage.setItem('netpeak_domains', JSON.stringify(domainList)), [domainList]);
  useEffect(() => localStorage.setItem('netpeak_hidden_domains', JSON.stringify(hiddenDomains)), [hiddenDomains]);
  useEffect(() => localStorage.setItem('serpstat_se', searchEngine), [searchEngine]);
  useEffect(() => { 
     if (data && viewMode === 'live') localStorage.setItem('netpeak_last_data', JSON.stringify(data));
  }, [data, viewMode]);

  const updateVisualConfig = (key: keyof VisualConfig, value: any) => {
    setVisualConfig(prev => ({ ...prev, [key]: value }));
  };

  const filteredData = useMemo(() => {
    if (!data) return null;
    const result: DashboardData = {};
    let hasVisible = false;
    domainList.forEach(d => {
      if (!hiddenDomains.includes(d) && data[d]) {
        // In snapshot mode, we skip region checks as we assume data is correct at time of snapshot
        if (viewMode === 'snapshot-view') {
           result[d] = data[d];
           hasVisible = true;
        } else {
           const health = getDomainHealth(d, data, searchEngine, isCollecting, progress);
           if (health.status !== 'error') {
              result[d] = data[d];
              hasVisible = true;
           }
        }
      }
    });
    return hasVisible ? result : null;
  }, [data, hiddenDomains, searchEngine, isCollecting, progress, viewMode, domainList]);

  const domainWarnings = useMemo(() => {
    if (viewMode === 'snapshot-view') return { fractional: [], excluded: [], mismatched: [] };
    const fractional: string[] = [];
    const excluded: string[] = [];
    const mismatched: string[] = [];
    domainList.forEach(d => {
      if (isRegionMismatch(d, searchEngine)) mismatched.push(d);
      else if (data) {
        const health = getDomainHealth(d, data, searchEngine, isCollecting, progress);
        if (health.status === 'warning' && health.label !== 'Region Mismatch') fractional.push(d);
        if (health.status === 'error') excluded.push(d);
      }
    });
    return { fractional, excluded, mismatched };
  }, [domainList, data, searchEngine, isCollecting, progress, viewMode]);

  const runAnalysis = async () => {
    const currentKey = localStorage.getItem('serpstat_key');
    if (domainList.length === 0) return;
    if (!currentKey) { setShowApiConfig(true); return; }
    setError(null);
    setIsCollecting(true);
    abortRef.current = false;
    try {
      const newData: DashboardData = {}; 
      for (let i = 0; i < domainList.length; i++) {
        if (abortRef.current) {
          setError({ message: t.stopped, explanation: "User interrupted the analysis." });
          break;
        }
        const domain = domainList[i];
        setProgress({ current: domain, percent: Math.round((i / domainList.length) * 100) });
        try {
          const result = await fetchDomainData(domain, currentKey, searchEngine);
          newData[domain] = result;
        } catch (err: any) {
          if (err.message.includes('401')) throw new Error('401');
          console.warn(`Fetch error for ${domain}:`, err.message);
        }
      }
      setData(prev => (abortRef.current ? { ...prev, ...newData } : newData));
      setProgress(null);
    } catch (err: any) {
      if (err.message === '401') {
         setError({ message: t.authFailed, explanation: t.authFailedDesc });
         setShowApiConfig(true);
      } else setError({ message: "Analysis interrupted", explanation: err.message });
    } finally {
      setIsCollecting(false);
      abortRef.current = false;
    }
  };

  const saveStateForUndo = () => {
    setUndoStack({
      domainList: [...domainList],
      hiddenDomains: [...hiddenDomains],
      data: data ? JSON.parse(JSON.stringify(data)) : null,
      selectedDomains: new Set()
    });
    setShowUndoToast(true);
    if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
    undoTimeoutRef.current = setTimeout(() => {
      setShowUndoToast(false);
      setUndoStack(null);
    }, 6000);
  };

  const triggerUndo = () => {
    if (!undoStack) return;
    setDomainList(undoStack.domainList);
    setHiddenDomains(undoStack.hiddenDomains);
    setData(undoStack.data);
    setShowUndoToast(false);
    setUndoStack(null);
    if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
  };

  const handleScreenshot = async () => {
    const targetRef = isFullscreenReport ? fullscreenRef : dashboardRef;
    if (!targetRef.current || !navigator.clipboard) return;
    setIsScreenshotting(true);
    try {
      const isOriginal = !isFullscreenReport;
      const width = targetRef.current.offsetWidth;
      const height = isOriginal ? targetRef.current.offsetHeight : targetRef.current.offsetHeight;

      const options = {
        quality: 1,
        pixelRatio: 2, // Optimized for Safari's user gesture timeout
        backgroundColor: '#ffffff',
        cacheBust: true,
        width,
        height,
        style: {
          transform: 'none',
          borderRadius: '0',
          boxShadow: 'none',
          margin: '0',
          padding: '0'
        }
      };

      // Safari requires clipboard writing to be tightly coupled with the user event.
      // Passing a Promise to ClipboardItem resolves this async issue.
      const clipboardPromise = toBlob(targetRef.current, options).then((blob: Blob | null) => {
        if (!blob) throw new Error('Failed to generate image blob');
        return blob;
      });

      // @ts-ignore - Safari 14+ specific constructor usage
      const item = new ClipboardItem({ 'image/png': clipboardPromise });
      await navigator.clipboard.write([item]);

      setScreenshotSuccess(true);
      setTimeout(() => setScreenshotSuccess(false), 3000);
    } catch (e) {
      console.error('Screenshot failed', e);
    } finally {
      setIsScreenshotting(false);
    }
  };

  // ------------------------------------
  // RENDER: AUTH / LOCKED
  // ------------------------------------
  if (viewMode === 'snapshot-locked') {
    return (
        <SnapshotAuth 
            lang={lang} 
            reportId={snapshotId!}
            hasOAuth={snapshotHasOAuth}
            onUnlock={(pw) => unlockSnapshot(snapshotId!, pw)} 
        />
    );
  }

  // ------------------------------------
  // RENDER: DASHBOARD (Live or Snapshot)
  // ------------------------------------
  const isReadOnly = viewMode === 'snapshot-view';

  return (
    <div className="flex h-screen bg-[#f8fafc] font-['Inter'] relative overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      {showUndoToast && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[500] animate-in slide-in-from-bottom-5 fade-in duration-300 w-[90%] sm:w-auto">
          <div className="bg-[#1e293b] text-white pl-6 pr-2 py-2 rounded-2xl shadow-2xl flex items-center gap-4 border border-slate-700/50 justify-between sm:justify-start">
            <span className="text-sm font-bold tracking-wide whitespace-nowrap">{t.deleted}</span>
            <div className="flex items-center gap-2">
              <button onClick={triggerUndo} className="px-4 py-2 bg-[#00a3ff] hover:bg-[#0088d6] text-white rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 min-h-[32px]"><Undo2 size={16} className="shrink-0" /> {t.undo}</button>
              <button onClick={() => setShowUndoToast(false)} className="p-2 text-slate-500 hover:text-white transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center"><X size={18} className="shrink-0" /></button>
            </div>
          </div>
        </div>
      )}

      {screenshotSuccess && (
        <div className="fixed top-10 left-1/2 -translate-x-1/2 z-[500] animate-in slide-in-from-top-5 fade-in duration-300">
           <div className="bg-emerald-500 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 border border-emerald-400"><CheckCircle2 size={20} className="shrink-0" /><span className="text-sm font-black tracking-wide uppercase">{t.screenshotCopied}</span></div>
        </div>
      )}

      {/* Sidebar */}
      <aside className={`w-[85%] sm:w-72 lg:w-56 xl:w-64 2xl:w-72 bg-white border-r border-slate-200 fixed lg:static h-full flex flex-col z-[70] transition-all duration-300 transform lg:transform-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-3 lg:p-4 flex flex-col h-full overflow-y-auto lg:overflow-hidden custom-scrollbar">
          <div className="flex items-center gap-3 lg:gap-4 mb-4 lg:mb-5 shrink-0 min-h-[44px]"><NetpeakLogo className="w-8 h-8 lg:w-8 lg:h-8 shrink-0" /><div className="flex flex-col"><span className="text-lg lg:text-base xl:text-lg font-black text-[#00A3FF] tracking-tight leading-none">Netpeak</span><span className="text-[9px] font-bold text-slate-500 tracking-[0.4em] mt-0.5 uppercase">Insights</span></div><button className="lg:hidden text-slate-400 ml-auto p-2 min-h-[44px] min-w-[44px] flex items-center justify-center" onClick={() => setIsSidebarOpen(false)}><X size={24} /></button></div>

          {isReadOnly ? (
             <div className="w-full mb-2 flex items-center justify-center gap-2 py-3 lg:py-2.5 rounded-2xl text-[10px] lg:text-[11px] font-bold bg-slate-100 text-slate-500 border border-slate-200 min-h-[44px] uppercase tracking-widest cursor-default">
                <Lock size={14} /> {t.readOnly}
             </div>
          ) : (
             isCollecting ? <button onClick={() => abortRef.current = true} className="w-full mb-2 flex items-center justify-center gap-3 py-3 lg:py-2.5 rounded-2xl text-[10px] lg:text-[11px] font-bold transition-all shadow-lg shrink-0 uppercase tracking-widest bg-rose-500 text-white hover:bg-rose-600 animate-pulse min-h-[44px]"><Square size={14} className="fill-current shrink-0" /> {t.stopReport}</button>
             : <button onClick={() => { runAnalysis(); setIsSidebarOpen(false); }} disabled={domainList.length === 0} className={`w-full mb-2 flex items-center justify-center gap-3 py-3 lg:py-2.5 rounded-2xl text-[10px] lg:text-[11px] font-bold transition-all shadow-lg shrink-0 uppercase tracking-widest min-h-[44px] ${domainList.length === 0 ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-[#00a3ff] text-white hover:bg-[#0088d6]'}`}><Play size={14} className="fill-current shrink-0" /> {t.runReport}</button>
          )}

          <nav className="space-y-1 lg:space-y-1 mb-3 lg:mb-4 shrink-0">{[{ id: 'overview', icon: Layout, label: t.overview }, { id: 'rankings', icon: Target, label: t.distribution }, { id: 'ai-overview', icon: Sparkles, label: t.aiOverview }, { id: 'index', icon: FileText, label: t.index }].map(tab => <button key={tab.id} onClick={() => { setActiveTab(tab.id); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-3 px-3 lg:px-4 py-3 lg:py-2 text-xs lg:text-xs xl:text-sm font-semibold rounded-xl transition-all min-h-[44px] lg:min-h-0 ${activeTab === tab.id ? 'text-[#00a3ff] bg-blue-50/50 border border-blue-100' : 'text-slate-700 hover:bg-slate-50'}`}><tab.icon size={16} className="shrink-0" /> {tab.label}</button>)}</nav>
          <div className="flex-1 min-h-0"></div>

          {!isReadOnly && (
            <div className="mt-2 lg:mt-3 pt-2 lg:pt-3 border-t border-slate-100 space-y-3 lg:space-y-2 shrink-0 mt-auto">
              <button onClick={() => setShowDomainManager(true)} className="w-full group flex items-center justify-between px-3 py-3 lg:py-2.5 rounded-xl bg-slate-50 border border-slate-200 hover:bg-white hover:border-blue-100 hover:shadow-md transition-all mb-2 min-h-[44px]"><div className="flex items-center gap-2"><div className="bg-[#00a3ff] text-white p-1.5 rounded-lg group-hover:scale-110 transition-transform"><Layers size={14} className="shrink-0" /></div><div className="flex flex-col items-start"><span className="text-[10px] lg:text-[11px] font-black text-slate-700 uppercase tracking-wider">{t.manageDomains}</span><span className="text-[9px] font-bold text-slate-400">{domainList.length} domains</span></div></div></button>
              <div><label className="text-[9px] font-bold text-slate-700 tracking-widest flex items-center gap-2 mb-1.5 lg:mb-1 ml-1 uppercase"><MapPin size={10} className="shrink-0" /> {t.region}</label><select value={searchEngine} onChange={(e) => setSearchEngine(e.target.value)} className="w-full bg-blue-50/30 border border-blue-100 rounded-xl py-2 lg:py-1.5 px-2.5 text-[10px] lg:text-[11px] font-bold text-[#00a3ff] focus:outline-none focus:ring-2 focus:ring-blue-200 transition-all cursor-pointer min-h-[36px]">{SEARCH_ENGINES.map(se => <option key={se.id} value={se.id}>{se.name}</option>)}</select></div>
              <button onClick={() => setShowApiConfig(true)} className="w-full flex items-center justify-between px-3 py-3 lg:py-2 rounded-xl text-slate-600 hover:text-[#00a3ff] hover:bg-blue-50 transition-all font-bold min-h-[44px] lg:min-h-[36px]"><span className="text-[9px] font-bold tracking-widest uppercase">{t.apiSettings}</span><Settings size={12} className="shrink-0" /></button>
            </div>
          )}
        </div>
      </aside>

      <main className="flex-1 h-full flex flex-col bg-[#f8fafc] overflow-hidden min-h-0 relative">
        {/* Read Only Banner */}
        {isReadOnly && (
          <div className="bg-slate-900 text-white px-4 py-2 text-[10px] font-bold uppercase tracking-widest flex items-center justify-center gap-2 shrink-0 relative z-50">
             <Lock size={12} className="text-[#00a3ff]" /> {t.snapshotMode}
          </div>
        )}

        {/* Header */}
        <header className="bg-white border-b border-slate-200 px-3 py-3 sm:px-4 flex flex-nowrap items-center justify-between z-50 shrink-0 shadow-sm/50 gap-3 relative">
          <div className="flex items-center gap-2 sm:gap-3 lg:gap-4 min-w-0 flex-1 relative z-0 overflow-hidden">
             <div className="lg:hidden flex gap-2 shrink-0"><button className="p-2.5 bg-white border border-slate-200 rounded-xl text-slate-600 hover:text-slate-900 hover:bg-slate-50 transition-all shadow-sm min-h-[44px] min-w-[44px] flex items-center justify-center active:scale-95" onClick={() => setIsSidebarOpen(true)}><Menu size={20} className="shrink-0" /></button>
             {!isReadOnly && <button onClick={() => setShowDomainManager(true)} className="p-2.5 bg-white border border-slate-200 rounded-xl text-slate-600 hover:text-[#00a3ff] hover:border-blue-100 hover:bg-blue-50 transition-all shadow-sm min-h-[44px] min-w-[44px] flex items-center justify-center active:scale-95" aria-label="Manage Domains"><Layers size={20} className="shrink-0" /></button>}
             </div>
             <div className="hidden sm:flex flex-col min-w-0 shrink"><h1 className="text-xl sm:text-2xl lg:text-3xl font-black text-[#1e293b] tracking-tight leading-none truncate">{t.title}</h1><p className="text-[#89d1ff] text-[8px] sm:text-[9px] font-black tracking-[0.2em] sm:tracking-[0.35em] mt-0.5 lg:mt-1 flex items-center gap-1.5 uppercase truncate"><Globe size={11} className="text-[#89d1ff] shrink-0" /> <span className="truncate">{t.subtitle}</span></p></div>
          </div>
          <div className="flex items-center gap-2 justify-end shrink-0 relative z-10 max-w-full">
          {data && activeTab === 'overview' && (
            <div className="hidden xl:flex items-center gap-2 bg-white p-1 rounded-xl border border-slate-200 shadow-sm shrink-0 overflow-x-auto no-scrollbar">
              <div className="flex items-center bg-slate-100/50 rounded-lg p-0.5">
                {(['visible', 'traff', 'keywords'] as const).map(m => <button key={m} onClick={() => setMetricType(m)} className={`px-3 lg:px-4 py-1.5 lg:py-1.5 text-[10px] sm:text-[11px] font-black rounded-lg transition-all uppercase whitespace-nowrap min-h-[28px] ${metricType === m ? 'bg-[#00a3ff] text-white shadow-md' : 'text-slate-700 hover:text-slate-900'}`}>{t[m as keyof typeof t]}</button>)}
              </div>
              <button onClick={() => setIsLogScale(!isLogScale)} className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${isLogScale ? 'bg-[#00a3ff] text-white shadow-md' : 'text-slate-500 hover:text-slate-900 bg-slate-50 border border-slate-200 hover:bg-slate-100'}`} title={t.logScale}>LOG</button>
            </div>
          )}
          {data && activeTab === 'rankings' && (
            <div className="hidden xl:flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm shrink-0 overflow-x-auto no-scrollbar">
              <button onClick={() => setRankingMode('domain')} className={`px-3 lg:px-4 py-1.5 lg:py-1.5 text-[10px] sm:text-[11px] font-black rounded-lg transition-all uppercase whitespace-nowrap min-h-[28px] ${rankingMode === 'domain' ? 'bg-[#00a3ff] text-white shadow-md' : 'text-slate-700 hover:text-slate-900'}`}>By Domain</button>
              <button onClick={() => setRankingMode('range')} className={`px-3 lg:px-4 py-1.5 lg:py-1.5 text-[10px] sm:text-[11px] font-black rounded-lg transition-all uppercase whitespace-nowrap min-h-[28px] ${rankingMode === 'range' ? 'bg-[#00a3ff] text-white shadow-md' : 'text-slate-700 hover:text-slate-900'}`}>By Range %</button>
            </div>
          )}
          <div className="flex bg-white border border-slate-200 rounded-xl p-1 shadow-sm shrink-0">{(['en', 'ua'] as const).map(l => <button key={l} onClick={() => setLang(l)} className={`px-3 lg:px-4 py-1.5 lg:py-1.5 text-[10px] sm:text-[11px] font-black rounded-lg transition-all uppercase min-h-[28px] ${lang === l ? 'bg-[#00a3ff] text-white shadow-md' : 'text-slate-700 hover:text-slate-900'}`}>{l === 'en' ? 'En' : 'Ua'}</button>)}</div>
          <div className="flex items-center gap-2 flex-nowrap shrink-0"><button onClick={() => setShowVisualSettings(true)} className="p-2 lg:p-2.5 bg-slate-50 hover:bg-blue-50 hover:text-[#00a3ff] text-slate-700 border border-slate-200 rounded-xl transition-all shadow-sm flex items-center gap-2 text-[10px] font-black tracking-widest uppercase shrink-0 min-h-[36px]"><Settings size={14} className="shrink-0" /><span className="hidden sm:inline">{t.settings}</span></button>
          {filteredData && <>
          <button onClick={handleScreenshot} disabled={isScreenshotting} className="p-2 lg:p-2.5 bg-[#00a3ff] hover:bg-[#0088d6] text-white rounded-xl transition-all shadow-sm flex items-center gap-2 text-[10px] font-black tracking-widest uppercase shrink-0 min-h-[36px] disabled:opacity-70 disabled:cursor-wait">{isScreenshotting ? <RefreshCw size={14} className="animate-spin shrink-0" /> : <Camera size={14} className="shrink-0" />}<span className="hidden sm:inline">{isScreenshotting ? t.capturing : t.screenshot}</span></button>
          <button onClick={() => setIsFullscreenReport(true)} className="p-2 lg:p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-slate-800 hover:text-[#00a3ff] hover:bg-blue-50 transition-all shadow-sm flex items-center gap-2 text-[10px] font-black tracking-widest uppercase shrink-0 min-h-[36px]"><Maximize2 size={14} className="shrink-0" /> <span className="hidden sm:inline">{t.fullscreen}</span></button></>}</div></div>
        </header>

        {/* Mobile Metric Switcher */}
        {data && activeTab === 'overview' && (
          <div className="xl:hidden px-2 py-2 bg-white border-b border-slate-200 flex items-center justify-between gap-2 shrink-0 z-40 shadow-sm animate-in slide-in-from-top-2 fade-in">
              <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200 w-full shadow-inner">
                {(['visible', 'traff', 'keywords'] as const).map(m => (
                  <button key={m} onClick={() => setMetricType(m)} className={`flex-1 py-1.5 text-[10px] font-black rounded-lg transition-all uppercase whitespace-nowrap ${metricType === m ? 'bg-white text-[#00a3ff] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
                    {t[m as keyof typeof t]}
                  </button>
                ))}
              </div>
              <button onClick={() => setIsLogScale(!isLogScale)} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all shadow-sm border ${isLogScale ? 'bg-[#00a3ff] text-white border-[#00a3ff]' : 'bg-slate-50 text-slate-600 border-slate-200'}`}>LOG</button>
          </div>
        )}
        {data && activeTab === 'rankings' && (
          <div className="xl:hidden px-2 py-2 bg-white border-b border-slate-200 flex items-center justify-between gap-2 shrink-0 z-40 shadow-sm animate-in slide-in-from-top-2 fade-in">
             <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200 w-full shadow-inner">
               <button onClick={() => setRankingMode('domain')} className={`flex-1 py-1.5 text-[10px] font-black rounded-lg transition-all uppercase whitespace-nowrap ${rankingMode === 'domain' ? 'bg-white text-[#00a3ff] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>By Domain</button>
               <button onClick={() => setRankingMode('range')} className={`flex-1 py-1.5 text-[10px] font-black rounded-lg transition-all uppercase whitespace-nowrap ${rankingMode === 'range' ? 'bg-white text-[#00a3ff] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>By Range %</button>
             </div>
          </div>
        )}

        <div className={`flex-1 flex flex-col ${isLandscapeMobile ? 'p-1' : 'p-2 sm:p-3 lg:p-4'} overflow-hidden relative min-h-0`}>
          {error && <div className="mb-4 bg-white border-l-8 border-rose-500 rounded-[1.5rem] p-4 lg:p-6 flex items-start gap-4 lg:gap-6 shadow-2xl w-full max-w-6xl animate-in fade-in slide-in-from-top-6 shrink-0 mx-auto"><div className="p-2 lg:p-3 bg-rose-50 text-rose-600 rounded-xl"><ShieldAlert size={20} className="shrink-0" /></div><div className="flex-1"><h3 className="text-rose-900 font-black text-base lg:text-lg tracking-tight">{error.message}</h3><p className="text-rose-700 text-xs mt-1 leading-relaxed font-bold">{error.explanation}</p></div><button onClick={() => setError(null)} className="text-slate-400 hover:text-slate-600 transition-colors p-2 min-h-[44px] min-w-[44px] flex items-center justify-center -mr-2 -mt-2"><X size={20} className="shrink-0" /></button></div>}

          {progress && <div className="mb-4 bg-gradient-to-br from-[#00a3ff] to-[#0088d6] rounded-[1.5rem] p-4 lg:p-6 text-white shadow-2xl w-full max-w-6xl animate-in zoom-in-95 shrink-0 mx-auto"><div className="flex items-center justify-between mb-2"><div className="flex items-center gap-3 lg:gap-4"><RefreshCw size={20} className="animate-spin text-white/60 shrink-0" /><span className="font-black text-xl lg:text-2xl tracking-tight truncate max-w-[200px] sm:max-w-md">Analyzing {progress.current}</span></div><span className="text-xl lg:text-2xl font-black">{progress.percent}%</span></div><div className="w-full bg-slate-900/15 h-2 rounded-full overflow-hidden"><div className="h-full bg-white shadow-[0_0_20px_rgba(255,255,255,0.7)] transition-all duration-1000 ease-out" style={{ width: `${progress.percent}%` }} /></div></div>}

          {data || (isCollecting && abortRef.current) ? (
            <div className="flex-1 w-full h-full flex flex-col min-h-0 animate-in fade-in duration-1000">
              <WarningsBanner domainWarnings={domainWarnings} lang={lang} />
              {filteredData ? (
                <div ref={dashboardRef} className="flex-1 flex flex-col min-h-0 bg-white rounded-[1.5rem] lg:rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden relative">
                  <div className={`shrink-0 ${isLandscapeMobile ? 'p-1 py-1' : 'p-3 sm:p-4 lg:p-5'} border-b border-slate-50 flex flex-col items-center text-center`}>
                    <h3 className="font-black tracking-tighter text-[#00A3FF] leading-tight" style={{ fontSize: isLandscapeMobile ? '16px' : `${visualConfig.headerFontSize}px` }}>
                      {activeTab === 'overview' ? (metricType === 'traff' ? t.trendTitle : metricType === 'visible' ? t.visibilityTitle : t.keywordsTitle) : (activeTab === 'rankings' ? t.serpTitle : activeTab === 'ai-overview' ? t.aioTitle : t.indexTitle)}
                    </h3>
                    {!isLandscapeMobile && <div className={`mt-1 transition-opacity duration-300 ${visualConfig.showSource ? 'opacity-100' : 'opacity-0 h-0 overflow-hidden'}`}><span className="text-[9px] font-bold text-slate-300 opacity-60 tracking-[0.5em] uppercase">{t.dataSource}</span></div>}
                  </div>
                  <div className={`flex-1 ${isLandscapeMobile ? 'p-0 pb-1' : 'p-2 sm:p-4 lg:p-4'} min-h-0 relative overflow-hidden flex flex-col`}>
                    <div className="flex-1 w-full h-full min-h-0">
                      {activeTab === 'overview' && <HistoryComparisonChart data={filteredData} metric={metricType} lang={lang} config={visualConfig} logScale={isLogScale} />}
                      {activeTab === 'rankings' && <StackedPositionChart data={filteredData} lang={lang} config={visualConfig} mode={rankingMode} />}
                      {activeTab === 'ai-overview' && <NeuroComparisonChart data={filteredData} lang={lang} config={visualConfig} />}
                      {activeTab === 'index' && <PagesComparisonChart data={filteredData} lang={lang} config={visualConfig} />}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center bg-white rounded-[1.5rem] p-10 lg:p-16 shadow-sm border border-slate-100 text-center mx-4 sm:mx-0"><div className="w-20 h-20 lg:w-24 lg:h-24 bg-slate-50 text-slate-400 rounded-[1.5rem] flex items-center justify-center mb-6 shadow-inner"><EyeOff size={40} className="shrink-0" /></div><h2 className="text-2xl lg:text-3xl font-black text-[#00A3FF] tracking-tight">{t.noVisible}</h2></div>
              )}
            </div>
          ) : !isCollecting && (
            <div className="flex items-center justify-center h-full w-full"><StandbyScreen onRunAnalysis={runAnalysis} lang={lang} /></div>
          )}
        </div>
      </main>

      {/* Fullscreen Report Modal */}
      {isFullscreenReport && filteredData && (
        <div className="fixed inset-0 bg-[#f8fafc] z-[200] flex flex-col animate-in fade-in duration-500 overflow-hidden h-full">
          <header className="bg-white border-b border-slate-200 px-3 py-3 sm:px-6 flex flex-nowrap items-center justify-between shadow-sm shrink-0 gap-3"><div className="flex items-center gap-3 sm:gap-4 min-w-0 flex-1 relative z-0 overflow-hidden"><NetpeakLogo className="w-8 h-8 sm:w-9 sm:h-9 shrink-0" /><div className="hidden sm:flex flex-col min-w-0 shrink"><h2 className="text-base sm:text-xl sm:text-2xl font-black tracking-tighter leading-none text-[#1e293b] truncate max-w-full">{activeTab === 'overview' ? t.trendTitle : activeTab === 'rankings' ? t.serpTitle : activeTab === 'ai-overview' ? t.aioTitle : t.indexTitle}</h2></div></div><div className="flex items-center gap-2 justify-end shrink-0 relative z-10 max-w-full"><button onClick={() => setShowVisualSettings(true)} className="flex items-center gap-2 px-3 sm:px-6 py-2 sm:py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-800 rounded-[1rem] font-black text-xs tracking-widest transition-all shadow-md active:scale-95 border border-slate-200 uppercase min-h-[36px] sm:min-h-[40px] shrink-0"><Settings size={16} className="shrink-0" /> <span className="hidden sm:inline">{t.settings}</span></button>
          <button onClick={handleScreenshot} disabled={isScreenshotting} className="flex items-center gap-2 px-3 sm:px-6 py-2 sm:py-2.5 bg-[#00a3ff] hover:bg-[#0088d6] text-white rounded-[1rem] font-black text-xs tracking-widest transition-all shadow-lg active:scale-95 border border-transparent uppercase min-h-[36px] sm:min-h-[40px] disabled:opacity-70 disabled:cursor-wait shrink-0">{isScreenshotting ? <RefreshCw size={16} className="animate-spin shrink-0" /> : <Camera size={16} className="shrink-0" />}<span className="hidden sm:inline">{isScreenshotting ? t.capturing : t.screenshot}</span></button>
          <button onClick={() => setIsFullscreenReport(false)} className="flex items-center gap-2 px-3 sm:px-6 py-2 sm:py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-800 rounded-[1rem] font-black text-xs tracking-widest transition-all shadow-md active:scale-95 border border-slate-200 uppercase min-h-[36px] sm:min-h-[40px] shrink-0"><Minimize2 size={16} className="shrink-0" /> <span className="hidden sm:inline">{t.close}</span></button></div></header>
          <div className="flex-1 p-2 sm:p-4 md:p-8 flex items-center justify-center bg-[#ffffff] overflow-hidden min-h-0 h-full">
             <div ref={fullscreenRef} className="w-full h-full max-w-[1920px] bg-white rounded-none sm:rounded-[2rem] border-none sm:border sm:border-slate-100 shadow-none sm:shadow-2xl p-4 sm:p-8 relative overflow-hidden flex flex-col min-h-0">
                <div className="shrink-0 p-2 sm:p-4 flex flex-col items-center text-center"><h3 className="font-black tracking-tighter text-[#00A3FF] mb-2 leading-tight" style={{ fontSize: `${visualConfig.headerFontSize}px` }}>{activeTab === 'overview' ? (metricType === 'traff' ? t.trendTitle : metricType === 'visible' ? t.visibilityTitle : t.keywordsTitle) : (activeTab === 'rankings' ? t.serpTitle : activeTab === 'ai-overview' ? t.aioTitle : t.indexTitle)}</h3></div>
                <div className="flex-1 min-h-0 relative w-full h-full flex flex-col">
                  <div className="flex-1 w-full h-full min-h-0">
                    {activeTab === 'overview' && <HistoryComparisonChart data={filteredData} metric={metricType} lang={lang} config={visualConfig} logScale={isLogScale} />}
                    {activeTab === 'rankings' && <StackedPositionChart data={filteredData} lang={lang} config={visualConfig} mode={rankingMode} />}
                    {activeTab === 'ai-overview' && <NeuroComparisonChart data={filteredData} lang={lang} config={visualConfig} />}
                    {activeTab === 'index' && <PagesComparisonChart data={filteredData} lang={lang} config={visualConfig} />}
                  </div>
                </div>
                <div className={`absolute bottom-4 right-8 transition-opacity duration-300 pointer-events-none ${visualConfig.showSource ? 'opacity-40' : 'opacity-0'}`}><span className="text-[9px] font-bold text-slate-400 tracking-[0.5em] uppercase">{t.dataSource}</span></div>
             </div>
          </div>
        </div>
      )}

      {/* Modals */}
      <SettingsModal 
        visible={showVisualSettings} 
        onClose={() => setShowVisualSettings(false)} 
        config={visualConfig} 
        onUpdateConfig={updateVisualConfig} 
        onLoadDemo={() => { saveStateForUndo(); setData(MOCK_DATA); setDomainList(Object.keys(MOCK_DATA)); setHiddenDomains([]); }} 
        lang={lang}
        currentData={data}
        currentDomainList={domainList}
      />

      <ApiConfigModal 
        visible={showApiConfig} 
        onClose={() => setShowApiConfig(false)} 
        lang={lang} 
      />

      {/* Domain Manager (Disabled in Read-Only) */}
      {!isReadOnly && (
        <DomainManager 
          visible={showDomainManager} 
          onClose={() => setShowDomainManager(false)} 
          domainList={domainList}
          hiddenDomains={hiddenDomains}
          data={data}
          searchEngine={searchEngine}
          isCollecting={isCollecting}
          progress={progress}
          onUpdateDomainList={(newList) => {
              const toRemove = domainList.filter(d => !newList.includes(d));
              if (toRemove.length > 0) saveStateForUndo();
              setDomainList(newList);
              if (toRemove.length > 0) {
                setData(prev => {
                  if (!prev) return null;
                  const next = { ...prev };
                  toRemove.forEach(d => delete next[d]);
                  return Object.keys(next).length > 0 ? next : null;
                });
              }
          }}
          onToggleVisibility={(d) => setHiddenDomains(prev => prev.includes(d) ? prev.filter(x => x !== d) : [...prev, d])}
          onRemoveDomains={(domainsToRemove) => {
              saveStateForUndo();
              setDomainList(prev => prev.filter(d => !domainsToRemove.includes(d)));
              setHiddenDomains(prev => prev.filter(d => !domainsToRemove.includes(d)));
              setData(prevData => {
                  if (!prevData) return null;
                  const newData = { ...prevData };
                  domainsToRemove.forEach(d => delete newData[d]);
                  return Object.keys(newData).length > 0 ? newData : null;
              });
          }}
          onClearAll={() => {
              saveStateForUndo();
              setDomainList([]);
              setHiddenDomains([]);
              setData(null);
              localStorage.removeItem('netpeak_last_data');
          }}
          lang={lang}
        />
      )}
    </div>
  );
};

export default App;

import express from 'express';
import path from 'path';
import { fileURLToPath } from 'url';
import { randomUUID, createHash } from 'crypto';
import { Firestore } from '@google-cloud/firestore';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = process.env.PORT || 8080;

// OAuth Configuration
const GOOGLE_CLIENT_ID = process.env.GOOGLE_CLIENT_ID;
const GOOGLE_CLIENT_SECRET = process.env.GOOGLE_CLIENT_SECRET;
const REDIRECT_URI = process.env.REDIRECT_URI || 'https://antako.online/presale-helper/api/auth/google/callback';

app.use(express.json({ limit: '50mb' }));

// ---------------------------------------------------------
// DATABASE CONNECTION (Firestore)
// ---------------------------------------------------------
// Cloud Run automatically authenticates this client using the service account
const firestore = new Firestore();
const SNAPSHOTS_COLLECTION = 'netpeak_snapshots';
const TOKENS_COLLECTION = 'netpeak_auth_tokens';

// ---------------------------------------------------------
// API ROUTES
// ---------------------------------------------------------

// Create Snapshot
app.post('/presale-helper/api/snapshot', async (req, res) => {
  try {
    const { data, domainList, password, allowedEmails } = req.body;

    if (!data || !domainList) {
      return res.status(400).json({ error: "Missing data payload" });
    }

    const id = randomUUID();

    let emailList = [];
    if (allowedEmails && typeof allowedEmails === 'string') {
      emailList = allowedEmails.split(',').map(e => e.trim().toLowerCase()).filter(e => e.length > 0);
    }

    const snapshot = {
      id,
      data: JSON.stringify(data), // Store large JSON blob as string if needed, or object
      domainList,
      password: password || null,
      allowedEmails: emailList.length > 0 ? emailList : null,
      createdAt: new Date().toISOString()
    };

    // Save to Firestore
    await firestore.collection(SNAPSHOTS_COLLECTION).doc(id).set(snapshot);

    res.json({ 
      success: true, 
      id, 
      url: `https://antako.online/presale-helper/report/${id}` 
    });
  } catch (error) {
    console.error('Snapshot creation failed:', error);
    res.status(500).json({ error: "Internal Server Error" });
  }
});

// Unlock Snapshot (via Password or Auth Token)
app.post('/presale-helper/api/snapshot/:id/unlock', async (req, res) => {
  try {
    const { id } = req.params;
    const { password, authToken } = req.body;

    // Fetch from Firestore
    const docRef = firestore.collection(SNAPSHOTS_COLLECTION).doc(id);
    const doc = await docRef.get();

    if (!doc.exists) {
      return res.status(404).json({ error: "Report not found" });
    }

    const snapshot = doc.data();
    // Parse data back if stored as string, otherwise use directly
    const snapshotData = typeof snapshot.data === 'string' ? JSON.parse(snapshot.data) : snapshot.data;

    let authorized = false;

    // 1. Check Password
    if (snapshot.password && password === snapshot.password) {
      authorized = true;
    }

    // 2. Check OAuth Token (Verify against Firestore Token Collection)
    if (authToken) {
      const tokenDoc = await firestore.collection(TOKENS_COLLECTION).doc(authToken).get();
      if (tokenDoc.exists) {
        const tokenData = tokenDoc.data();
        if (tokenData.reportId === id && tokenData.expires > Date.now()) {
          authorized = true;
        }
      }
    }

    // 3. If Public (no password, no emails)
    if (!snapshot.password && (!snapshot.allowedEmails || snapshot.allowedEmails.length === 0)) {
        authorized = true;
    }

    if (!authorized) {
      return res.status(403).json({ error: "Unauthorized access" });
    }

    res.json({
      data: snapshotData,
      domainList: snapshot.domainList,
      createdAt: snapshot.createdAt
    });

  } catch (error) {
    console.error('Snapshot retrieval failed:', error);
    res.status(500).json({ error: "Internal Server Error" });
  }
});

// Check Status
app.get('/presale-helper/api/snapshot/:id/status', async (req, res) => {
  try {
    const { id } = req.params;
    const doc = await firestore.collection(SNAPSHOTS_COLLECTION).doc(id).get();

    if (!doc.exists) return res.status(404).json({ error: "Not Found" });

    const snapshot = doc.data();
    const hasPassword = !!snapshot.password;
    const hasOAuth = snapshot.allowedEmails && snapshot.allowedEmails.length > 0;

    res.json({
      id: snapshot.id,
      isLocked: hasPassword || hasOAuth,
      authMethods: {
          password: hasPassword,
          oauth: hasOAuth
      },
      createdAt: snapshot.createdAt
    });
  } catch (e) {
    console.error("Status Check Error", e);
    res.status(500).json({ error: "Server Error" });
  }
});

// ---------------------------------------------------------
// OAUTH FLOW
// ---------------------------------------------------------

// 1. Redirect to Google
app.get('/presale-helper/api/auth/google/login', (req, res) => {
  const { reportId } = req.query;
  if (!GOOGLE_CLIENT_ID) return res.status(500).send("Server missing Google Credentials");

  const scope = 'https://www.googleapis.com/auth/userinfo.email';
  const url = `https://accounts.google.com/o/oauth2/v2/auth?client_id=${GOOGLE_CLIENT_ID}&redirect_uri=${encodeURIComponent(REDIRECT_URI)}&response_type=code&scope=${scope}&state=${reportId}`;

  res.redirect(url);
});

// 2. Google Callback
app.get('/presale-helper/api/auth/google/callback', async (req, res) => {
    const { code, state: reportId } = req.query;

    if (!code || !reportId) return res.status(400).send("Invalid request");

    try {
        // Exchange code for tokens
        const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
            method: 'POST',
            headers: {'Content-Type': 'application/x-www-form-urlencoded'},
            body: new URLSearchParams({
                code: code.toString(),
                client_id: GOOGLE_CLIENT_ID,
                client_secret: GOOGLE_CLIENT_SECRET,
                redirect_uri: REDIRECT_URI,
                grant_type: 'authorization_code'
            })
        });

        const tokens = await tokenRes.json();
        if (tokens.error) throw new Error(tokens.error_description);

        // Get User Email
        const userRes = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
            headers: { Authorization: `Bearer ${tokens.access_token}` }
        });
        const user = await userRes.json();
        const userEmail = user.email.toLowerCase();

        // Check Permissions
        const docRef = firestore.collection(SNAPSHOTS_COLLECTION).doc(reportId.toString());
        const doc = await docRef.get();

        if (!doc.exists) return res.status(404).send("Report not found");
        const snapshot = doc.data();

        if (!snapshot.allowedEmails || !snapshot.allowedEmails.includes(userEmail)) {
            return res.status(403).send(`<h1>Access Denied</h1><p>The email <b>${userEmail}</b> is not on the allowed list for this report.</p><a href="/presale-helper/report/${reportId}">Go Back</a>`);
        }

        // Generate temp token and store in Firestore (Valid for 2 hours)
        const tempToken = createHash('sha256').update(randomUUID()).digest('hex');
        await firestore.collection(TOKENS_COLLECTION).doc(tempToken).set({
            reportId: reportId.toString(),
            email: userEmail,
            expires: Date.now() + (1000 * 60 * 60 * 2), // 2 hours
            createdAt: Date.now()
        });

        // Redirect back to app
        res.redirect(`https://antako.online/presale-helper/report/${reportId}?token=${tempToken}`);

    } catch (e) {
        console.error("OAuth Error:", e);
        res.status(500).send("Authentication failed");
    }
});

// ---------------------------------------------------------
// STATIC SERVING
// ---------------------------------------------------------
app.use((req, res, next) => {
  const host = req.get('host');
  const forwardedHost = req.headers['x-forwarded-host'];
  if (!forwardedHost && host && host.includes('run.app')) {
    return res.redirect(301, `https://antako.online/presale-helper${req.url}`);
  }
  next();
});

app.use('/presale-helper', express.static(path.join(__dirname, 'dist')));
app.use(express.static(path.join(__dirname, 'dist')));

app.get(['/presale-helper', '/presale-helper/*', '/'], (req, res) => {
  res.sendFile(path.resolve(__dirname, 'dist', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
